/* Capacités des fiches ressources Éduscol EPS : collège (déc. 2009, niveaux 1 et 2) et lycée (fév. 2011, niveaux 3 et 4).
   Réutilisation libre dans le cadre de l'enseignement scolaire, hors exploitation commerciale.
   cp = compétence propre, a = compétence attendue, p = pratiquant, r = autres rôles. */
window.EPS_REFERENTIEL={"N1":{"Demi-fond":{"cp":1,"a":"Réaliser la meilleure performance possible dans un enchaînement de 2 ou 3 courses d’une durée différentes (de 3 à 9 minutes), en maîtrisant différentes allures adaptées à la durée et à sa VMA, en utilisant principalement les repères extérieurs et quelques repères sur soi. Etablir un projet de performance et le réussir à 1 km/h près","p":["Adopter une foulée économique et l’adapter (amplitude - fréquence) en fonction de la vitesse prévue dans ses projets","Solliciter sa puissance et sa capacité aérobie pour réaliser la meilleure performance.","Identifier et adopter des vitesses de course (allures) différentes en fonction de la durée de course et de sa VMA.","Apprécier l’efficacité des ses actions, réguler et maintenir son allure à 1km/h près grâce aux repères externes et au ressenti","Adopter un rythme et un mode respiratoires adaptés à son allure du moment.","Etre actif - marcher, trottiner, s’étirer - pendant les temps de récupération.","Prendre son pouls après un effort.","Construire, réguler et respecter un projet de course en fonction de l’épreuve dans son ensemble et à partir de l’analyse de ses résultats."],"r":["Prendre des repères sur le balisage du parcours et les signaux sonores.","Utiliser un chronomètre.","Communiquer des résultats et informations fiables, précises et claires."]},"Course de haies":{"cp":1,"a":"Réaliser la meilleure performance possible sur une distance de 30 à 40 mètres, avec 3 à 4 haies basses, en enchaînant des courses inter obstacles avec un nombre identifié d’appuis sur le parcours le plus adapté à ses possibilités. Respecter les règles de sécurité Assumer au sein d’un groupe restreint les rôles d’observateur et de chronométreur.","p":["Utiliser et mobiliser les ressources de la filière anaérobie alactique.","Utiliser et mobiliser ses ressources neuromusculaires pour une vitesse de réaction et vitesse gestuelle optimales.","Mobiliser et coordonner l’action des bras et des jambes lors d’un départ debout au signal.","Courir sans ralentir avant et après le franchissement des obstacles.","Courir au plus près de l’axe de déplacement.","Impulser loin de la haie, attaquer genou haut dans l’axe.","Intégrer un rythme rapide d’appuis et le maintenir.","Poursuivre son effort après la dernière haie.","Analyser l’efficacité de ses actions (ressentis et observations transmises) et choisir le parcours le plus adapté à ses possibilités.","S’échauffer sous le contrôle de l’enseignant en vue de l’effort à produire, proposer des exercices appropriés."],"r":["Installer les parcours en respectant les règles de sécurité.","Utiliser le chronomètre, à partir des repères de déclenchement du départ et de franchissement de la ligne d’arrivée.","Compter le nombre d’appuis entre les haies.","Communiquer des résultats et informations fiables, précises et claires."]},"Saut en hauteur":{"cp":1,"a":"A partir d’un élan étalonné de 4 à 6 appuis, réaliser la meilleure performance possible, de façon sécurisée, en alignant le trajet avec la trajectoire. Assumer dans un groupe restreint le rôle d’observateur.","p":["Prendre et repérer une marque de départ de course d’élan","Partir de sa marque avec le bon pied devant pour déclencher une impulsion devant le premier tiers ou la première moitié du tapis selon le type de franchissement.","Mettre en relation le nombre d’appuis et le pied avant au départ pour respecter le nombre d’appuis demandé.","Déclencher une impulsion efficace par une action complète de la jambe d’appel (impulsion longue orientée vers le haut) et une action des segments libres (lancer/bloquer).","Aligner les 3 derniers appuis de course.","Reproduire une course d’élan régulière, étalonnée, à vitesse optimale."],"r":["Identifier les caractéristiques d’un élan : nombre d’appuis, accélération, pied d’appel, forme de la course.","Observer un camarade en référence aux observables définis.","Comparer des performances pour en tirer des conclusions sur l’efficacité.","Communiquer des informations fiables, précises et claires."]},"Lancer de javelot":{"cp":1,"a":"A partir d’un élan réduit, réaliser la meilleure performance possible, par un lancer à bras cassé en recherchant un point de chute de l’engin dans l’axe de l’élan. Respecter les règles de sécurité.","p":["Lancer à bras cassé au-dessus de l’épaule dans l’axe de l’élan, le javelot tenu entre deux doigts en butée contre la cordée et paume de la main orientée vers le haut, coude au-dessus de l’épaule, main au-dessus du coude.","Eloigner la main lanceuse vers l’arrière en allongeant le bras.","Lancer en opposant main lanceuse et pied avant.","Déclencher le lancer à partir de la pose du pied avant.","En phase finale, finir grand et équilibré sur deux appuis, face à la zone de chute.","Prendre des informations visuelles au cours de l’élan (pointe du javelot près de l’œil, « regarder sa montre » avec le bras libre) et pendant le lancer (regard orienté vers la zone de chute)."],"r":["Identifier les caractéristiques d’un lancer et de sa validation (zone d’élan, lieu et nature de la chute du javelot).","Observer la position du javelot lors de l’élan et du lancer d’un de ses camarades.","Se placer de façon sécuritaire durant le lancer de son camarade pour observer et communiquer des informations fiables précises et claires.","Communiquer des résultats et informations fiables, précises et claires."]},"Multibond":{"cp":1,"a":"A partir d’un élan étalonné de 6 à 8 appuis, réaliser la meilleure performance possible sur 3 à 5 bonds enchaînés et équilibrés. Assumer dans un groupe restreint les rôles d’observateur.","p":["Augmenter sa vitesse au cours de sa course d’élan et ne pas piétiner.","Adopter une attitude de course « haute » sur ses appuis et relâchée sur les derniers appuis.","Enchaîner les 3 à 5 bonds demandés, en restant équilibré dans l’axe du déplacement.","Placer son regard loin devant soi.","Utiliser ses segments libres.","Anticiper les rebonds au sol lors de la suspension par une organisation corporelle personnelle adaptée.","Expérimenter différentes formes ou enchaînements de bonds.","Optimiser sa distance de saut par un ramené des jambes lors de la réception.","Reproduire des performances de niveau sensiblement identique en exploitant au mieux ses potentialités et plusieurs longueurs d’élan.","Etre actif, marcher, s’étirer, se remobiliser entre les différents essais."],"r":["Identifier les caractéristiques d’un élan : nombre d’appuis, accélération, pied d’appel, dans la zone autorisée.","Observer l’équilibre du saut (dans l’axe ou pas).","Comparer des performances pour en tirer des conclusions sur l’efficacité.","Communiquer des résultats et informations fiables précises et claires."]},"Relais-vitesse":{"cp":1,"a":"Réaliser la meilleure performance possible dans un relais de 2 x 30 mètres en transmettant le témoin en déplacement, dans une zone imposée. Tenir les rôles de donneur et de receveur. Assumer au sein d’un groupe restreint le rôle d’observateur.","p":["Enchaîner des efforts de type anaérobie alactique en veillant à une récupération adaptée pour exploiter une vitesse de course maximale.","Pour le donneur, adopter une posture de départ debout permettant une mise en action rapide et maintenir sa vitesse maximale jusqu'à la transmission du témoin.","Pour le receveur, adopter une posture de départ permettant une prise d’informations vers l’arrière en même temps qu’une mise en action rapide et se mettre en action à vitesse maximum.","Maîtriser la direction de sa course dans le couloir à vitesse maximale","Dissocier le train supérieur du train inférieur pour donner / recevoir le témoin tout en conservant sa vitesse sans perdre son équilibre.","Trouver la meilleure marque de passage pour coordonner les vitesses donneur/relayeur.","Communiquer à partir de critères précis observables pour réguler la prise de marque."],"r":["Identifier les caractéristiques d’une transmission efficace et de sa validation.","Observer la transmission d’un témoin en fonction de critères précis.","Communiquer des résultats et informations fiables, précises et claires."]},"Natation longue":{"cp":1,"a":"A partir d’un départ plongé ou dans l’eau réaliser, sur une durée de 6 minutes, la meilleure performance possible en nage ventrale et dorsale en optimisant l’équilibre, la respiration et les phases de coulée. Respecter les règles de sécurité et d’hygiène. Assumer le rôle d’observateur.","p":["Assurer un départ plongé ou dans l’eau en utilisant pleinement la poussée sur le plot ou le bord, corps gainé et profilé à l‘entrée ou lors de la coulée, une reprise de nage dès que la vitesse décroît.","Immerger les voies respiratoires le plus souvent possible en nage ventrale pour maintenir la tête dans l’axe du corps, le regard orienté vers le fond et légèrement vers l’avant pendant la nage.","Préserver ou rétablir l’équilibre horizontal pour réduire les résistances lors des déplacements en nage dorsale et ventrale : placement de la tête, dissociation tête / tronc lors de l’inspiration.","Adopter un mode de déplacement économique permettant une certaine continuité dans le temps de l’effort : amplitude des trajets moteurs, utilisation des temps de glisse, relâchement.","Pousser avec les jambes contre le mur pour réaliser une coulée en immersion complète","Respirer sans interrompre les actions propulsives.","Réaliser une expiration aquatique active, la plus complète possible.","S’informer tout en se déplaçant à partir de repères situés au fond du bassin et sur les lignes d’eau.","Gérer son effort pour nager avec régularité tout en visant la meilleure performance possible."],"r":["L’observateur : identifier le ou les critère(s) en responsabilité : position de la tête / à la surface, modalités d’inspiration et d’expiration, efficacité des coulées.","L’observateur : noter et communiquer des résultats et des informations fiables."]},"Natation de vitesse":{"cp":1,"a":"A partir d’un départ plongé ou dans l’eau réaliser, la meilleure performance possible sur une distance de 25 mètres en crawl en adoptant l’équilibre et les trajets moteurs les plus efficaces. Respecter les règles de sécurité et d’hygiène. Assumer le rôle d’observateur.","p":["Assurer un départ plongé ou dans l’eau en utilisant pleinement la poussée sur le plot ou le bord, corps gainé et profilé à l‘entrée ou lors de la coulée.","Exploiter la vitesse acquise lors du départ pour reprendre la nage en effectuant des battements de jambes en premier lorsque la vitesse décroit, tête dans l’alignement du corps.","Agrandir le trajet moteur des bras en avant des épaules, dans la profondeur et en arrière tout en restant proche de l’axe du corps.","Chercher « l’appui » en avant et accélérer les fins de trajets propulsifs.","Réaliser des battements de jambes continus et réguliers pour maintenir l’axe du corps à l’horizontal et réduire le phénomène de lacet.","Immerger les voies respiratoires le plus souvent possible pour maintenir la tête dans l’axe du corps, le regard orienté vers le fond et l’avant.","Inspirer latéralement et brièvement pour limiter les déséquilibres corporels et la discontinuité propulsive.","Finir sa course en touchant le mur sans ralentir.","Gérer sa course en jouant sur l’amplitude des trajets moteurs pour réaliser la meilleure performance possible."],"r":["L’observateur : identifier le ou les critère(s) en responsabilité : position de la tête / à la surface, nombre de coups de bras.","L’observateur : noter et communiquer des résultats et des informations fiables."]},"Canoë-kayak":{"cp":2,"a":"Conduire un déplacement en maîtrisant la direction de son embarcation sans appréhension. Respecter les consignes de sécurité et l’environnement. Accepter le dessalage.","p":["S’équiper seul et vérifier son matériel.","Embarquer et débarquer seul (berge aménagée ou non).","Utiliser les calages de l’embarcation pour explorer les limites de la stabilité latérale du bateau.","Réaliser un parcours en fixant son regard vers la cible.","Aller droit et éviter les obstacles simples sur de l’eau calme ou coulante.","Ressentir et contrôler les éventuels dérapages de l’arrière du bateau.","Varier les actions de pagaie en force, amplitude, orientation.","Utiliser des actions de pagaie pour se tirer, tourner ou se repousser.","S’arrêter vite face à un obstacle sans tourner.","Se déplacer en marche arrière.","Se déplacer sans fatigue sur des distances significatives permettant la découverte du milieu naturel proche.","Lors d’un dessalage volontaire, sortir ou quitter l’embarcation sans panique.","Nager en eau profonde avec du matériel pour rejoindre la rive (si les conditions les permettent)","Prendre en compte le résultat de ses actions pour identifier les règles efficientes."],"r":["Intervenir sur l’eau à la demande du professeur afin de ne pas produire un « sur incident ».","Aider à soulever et à porter un bateau dos placé.","Aider un nageur à remonter dans un bateau collectif.","A terre, vider un bateau plein d’eau à deux.","De l’observateur : observer les critères simples.","De l’observateur : noter correctement et transmettre les résultats de son observation sur le pagayeur ou sur le milieu naturel."]},"Course d’orientation":{"cp":2,"a":"Choisir et conduire un déplacement pour trouver des balises, à l’aide d’une carte, en utilisant essentiellement des lignes directrices simples dans un milieu nettement circonscrit. Gérer l’alternance des efforts. Respecter les règles de sécurité et l’environnement","p":["Identifier et associer les éléments simples du terrain avec leur représentation graphique sur la carte, (relation terrain-carte).","Identifier et associer les lignes simples de la carte avec leurs présences sur le terrain (relation carte-terrain).","Reconnaître et progresser dans l’espace délimité par les « lignes d’arrêt » prédéfinies.","Choisir et planifier son itinéraire d’un point à un autre en s’appuyant sur des éléments connus (chemins, carrefour, maison, mare, limites de végétation nettes).","Orienter la carte à l’aide des éléments situés sur le terrain, la réorienter à chaque changement de direction, se situer sur la carte à chaque arrêt.","Suivre avec son pouce sur la carte sa progression sur le terrain.","Courir sur les lignes directrices simples (chemins essentiellement) d’un point de décision à l’autre.","Mémoriser les éléments marquants (points d’appui) entre deux points de décision, les repérer pendant la course.","Récupérer pendant les arrêts (poinçonnage).","Reconnaître et contourner les propriétés privées, les cultures.","Adapter son allure au cours de l’itinéraire : partir à allure « moyenne » pour contrôler la direction prise ; courir à son allure jusqu’au dernier point sûr avant la balise, ralentir à ce moment voir marcher pour ne pas rater le poste.","Adapter son allure en fonction de son partenaire."],"r":["Poser et contrôler un poste simple.","Ramasser les balises d’un parcours connu.","Renseigner et corriger les cartons de contrôle.","Noter avec précision temps de départ et temps d’arrivée.","Echanger avec son partenaire les informations observées sur la carte et le terrain pour orienter la carte et choisir l’itinéraire."]},"Escalade":{"cp":2,"a":"Choisir et conduire un déplacement pour grimper, en moulinette, deux voies différentes à son meilleur niveau en privilégiant l’action des membres inférieurs. Assurer un partenaire en toute sécurité.","p":["S’équiper d’un harnais, l’ajuster (taille et cuisses), vérifier les retours de sangles (si nécessaire).","Faire son nœud d’encordement, avec nœud d’arrêt, sur le pontet.","Identifier des voies : le départ, le sommet (dernière prise et relai concerné), le niveau de cotation, la couleur, la densité, l’emplacement et la nature des prises.","S’assurer visuellement du bon coulissage de la corde en partie haute de voie.","S’équilibrer pour se reposer et observer.","Identifier et utiliser des prises permettant des positions de moindre effort (PME) simples.","S’équilibrer sur les pieds pour relâcher un bras.","Eloigner les épaules de la paroi pour observer et choisir les prises à utiliser.","S’équilibrer pour progresser.","Favoriser la montée des pieds sur les prises avant celle des mains.","Utiliser l’avant du pied et les bords internes en priorité pour trouver des appuis solides.","Transférer le bassin sur l'appui de pied solide pour conjuguer les actions de pousser et de tirer (appuis dynamiques de progression).","Enchainer la voie sans s’asseoir dans son harnais (« sans faute »).","Descendre assis dans le baudrier les pieds à plat sur le mur ou en dé-escaladant.","Communiquer avec ses assureurs en utilisant les termes spécifiques (sec, du mou, avaler).","Gérer son énergie pour atteindre le sommet de la voie."],"r":["L’assureur/ contre assureur : s’équiper d’un harnais, l’ajuster (taille et cuisses), vérifier les retours de sangles (si nécessaire).","L’assureur/ contre assureur : installer le système d’assurage sur la corde et sur le pontet du harnais (mousqueton à vis fermé).","L’assureur/ contre assureur : maîtriser la méthode de l’assurage en moulinette en 5 temps en contrôlant la tension de la corde (tendre sans tirer).","L’assureur/ contre assureur : assurer en conservant une attention constante sur le grimpeur.","L’assureur/ contre assureur : communiquer et bloquer le grimpeur en position de descente avant d’assurer son retour à vitesse lente et sans à-coup (les deux mains en dessous du système d’assurage).","L’assureur/ contre assureur : parer un grimpeur en traversée ou en bloc (se placer derrière, les mains au niveau du dos du grimpeur).","L’observateur : garantir la validité d’une ascension.","L’observateur : identifier les prises utilisables et renseigner le grimpeur en cas de besoin."]},"Aérobic":{"cp":3,"a":"Présenter une routine collective synchronisée, tenant compte de l’orientation des formations dans l’espace scénique, sur un support musical (de 120 BPM à 130 BPM) en choisissant un ou deux éléments parmi les quatre familles, combinés à des pas de base et associés à des mouvements de bras simples. Observer et apprécier les prestations à partir de critères simples.","p":["Doser son énergie, son tonus musculaire et gérer son effort sur l’ensemble de la prestation.","Réaliser des difficultés simples en respectant les exigences techniques minimales.","Prendre et maintenir une posture alignée lors de la réalisation des difficultés.","Réaliser les pas de base spécifiques à l’activité et les synchroniser avec la pulsation musicale et ses partenaires.","Coordonner ponctuellement des pas de base (composés principalement de pas marchés) avec des mouvements de bras simples (symétriques).","Mémoriser un bloc de pas (quatre fois huit temps), une séquence imposée.","Reproduire des séquences chorégraphiées et une séquence « miroir » simple.","Réaliser des transitions simples (descendre au sol et se relever sur la musique)."],"r":["Le chorégraphe : choisir une ou deux éléments, parmi les quatre familles, adaptés aux ressources du groupe.","Le chorégraphe : agencer des séquences chorégraphiques en y incluant les éléments de difficulté.","Le chorégraphe : choisir deux ou trois formations, passer de l’une à l’autre par des trajectoires simples (directes), en changeant d’orientation dans l’espace.","L’observateur : repérer les éléments de difficulté.","L’observateur : apprécier leur réalisation à partir d’un ou deux critères simples et précis."]},"Acrosport":{"cp":3,"a":"Concevoir et présenter un enchaînement maîtrisé d’au moins 4 figures acrobatiques, montées et démontées de façon sécurisée, choisies en référence à un code commun, reliées par des éléments gymniques ou chorégraphiques. Assumer au moins deux des trois rôles : voltigeur, porteur, aide. Observer et apprécier les prestations à partir de critères simples.","p":["Mémoriser son rôle dans l’enchaînement.","Coordonner ses actions avec celles des autres.","Maîtriser des éléments gymniques simples.","Doser son énergie, son tonus et gérer son effort sur l’ensemble de la prestation.","Porteur : mettre en place les placements de base : dos plat, bassin en rétroversion (gainage), parties porteuses à la verticale des appuis ou au somment d’un triangle.","Porteur : etre stable sur ses appuis en élargissant la base de sustentation.","Porteur : contracter les muscles pour verrouiller les articulations et stabiliser l’ensemble du corps.","Porteur : réaliser des saisies précises et efficaces.","Voltigeur : se positionner précisément et rapidement (sans précipitation).","Voltigeur : prendre des appuis stables sur le porteur avec et sur des surfaces larges et verrouillées.","Voltigeur : prévoir son espace de réception.","Aide : accompagner et équilibrer le montage et le démontage de la figure.","Aide : prévoir le lieu de chute possible et se placer à l’endroit le plus « risqué » en levant les bras vers le voltigeur.","Aide : adopter une posture dynamique permettant d’intervenir rapidement."],"r":["Le chorégraphe : choisir les figures acrobatiques adaptées aux ressources de chacun (les plus difficiles possibles, mais maîtrisées et coordonnées).","Le chorégraphe : rechercher la continuité dans la liaison des figures.","Le chorégraphe : rechercher des éléments chorégraphiques originaux, esthétiques.","L’observateur : repérer les figures acrobatiques.","L’observateur : apprécier leur réalisation à partir d’un ou deux critères simples et précis."]},"Gymnastique":{"cp":3,"a":"Dans le respect des règles de sécurité, sur un parcours multi agrès, présenter un ensemble d’éléments gymniques simples maîtrisés, combinés ou non, illustrant les actions «tourner, se renverser». Aider un camarade à réaliser un élément simple. Observer et apprécier les prestations à partir de critères simples.","p":["Choisir des éléments gymniques adaptés à ses ressources les plus difficiles possibles mais maîtrisés.","Réaliser, sur un espace aménagé ou non, les éléments gymniques intégrant entre autres, les actions suivantes : tourner en avant corps groupé en roulant autour d’un axe transversal (roulade avant tour d’appui avant)","Réaliser, sur un espace aménagé ou non, les éléments gymniques intégrant entre autres, les actions suivantes : tourner en arrière corps groupé autour d’un axe transversal (roulade arrière, tour d’appui arrière, renversement)","Réaliser, sur un espace aménagé ou non, les éléments gymniques intégrant entre autres, les actions suivantes : tourner corps tendu autour d’un axe longitudinal (demi-tour en suspension)","Réaliser, sur un espace aménagé ou non, les éléments gymniques intégrant entre autres, les actions suivantes : se renverser sur les bras tendus vers l’avant en appui manuel (ATR, sortie en appui corps tendu)","Réaliser, sur un espace aménagé ou non, les éléments gymniques intégrant entre autres, les actions suivantes : se renverser sur les bras tendus latéralement (roue)","Se réchapper d’une position manuelle renversée en avançant une main pour amorcer une rotation après l’ATR","Coordonner des actions motrices variées","Doser son énergie, son tonus musculaire et gérer son effort sur l’ensemble de sa prestation"],"r":["L’aide : se situer au maximum à une distance d’un bras tendu du gymnaste.","L’aide : réaliser les gestes d’aide en accompagnant et en tenant le gymnaste sur les zones précisées et imposées.","L’observateur : reconnaître les éléments gymniques simples et les différentes postures (groupée, alignée).","L’observateur : apprécier les éléments observés à partir d’un ou deux critères de réussite simples et précis."]},"Gymnastique rythmique":{"cp":3,"a":"Présenter un enchaînement en duo, en organisant des manipulations d’engins en relation avec des déplacements corporels dans un espace défini. Maîtriser ses émotions et accepter le regard des autres. Observer et apprécier les prestations à partir de critères simples.","p":["Animer l’engin par le corps en contrôlant l’énergie transmise.","Doser son tonus musculaire pour rester équilibré.","Gérer son effort sur l’ensemble de la prestation.","Combiner une manipulation d’engin avec un élément corporel de type pas courus, sautillés, chassés, tournants, sauts.","Enchaîner les actions de balancer, lancer-rattraper, passer dedans, dessous, dessus.","Réaliser des circumductions, des élans, des mouvements en huit, des rotations, des échanges en respectant les logiques de plans et de sens.","Coordonner ses actions avec le partenaire, de manière synchronisée.","Varier les relations avec le partenaire : corps/corps, corps/engin, engin/engin."],"r":["Le chorégraphe : choisir des éléments manipulatoires et corporels adaptés aux ressources de chacun (les plus difficiles possibles mais maîtrisés et coordonnés).","Le chorégraphe : repérer et marquer les temps forts du mouvement sur la musique.","Le chorégraphe : exploiter au mieux l’espace chorégraphique.","L’observateur : repérer les éléments et les formes produites par le duo.","L’observateur : apprécier leur réalisation à partir d’un ou deux critères simples et précis."]},"Arts du cirque":{"cp":3,"a":"Composer et présenter dans un espace orienté un numéro collectif organisé autour d’un thème incorporant à un jeu d’acteur des éléments simples issus d’au moins deux des trois familles. Maîtriser ses émotions et accepter le regard des autres. Observer avec attention et apprécier avec respect les différentes prestations.","p":["Enchaîner plusieurs figures avec un même objet ou engin dans « au moins 2 des 3 familles »","Se déplacer et s’équilibrer sur un engin à stabilité précaire en respectant les règles de sécurité et d’équilibre.","Manipuler un ou plusieurs objets ou engins différents en les lançant, attrapant, roulant, basculant, arrêtant pour produire des trajectoires précises.","Partager ses objets avec un partenaire : échanger, mélanger.","Réaliser des figures acrobatiques simples, agencées de manière originale, synchronisée, inhabituelle: roulade, porter, pyramide collective.","Réaliser des séquences collectives reproductibles optimisant les possibilités de chacun.","Mémoriser les différentes formes corporelles à reproduire, les formes de groupements, les rôles, les espaces et les durées.","Entrer en relation ou contact simple avec ses partenaires (mains, bustes, regard).","S’orienter dans l’espace avec ses partenaires par rapport au spectateur.","Construire de brefs « moments » solo à partir de savoir-faire techniques simples.","Entrer dans son rôle d’acteur.","Lever les yeux, regarder simplement.","Varier les rythmes, ralentir, marquer des arrêts.","Eliminer les gestes parasites.","S’appuyer sur un accessoire : masque, nez, costume, maquillage pour souligner un trait."],"r":["Le metteur en scène : créer dans le cadre de composition proposé par l’enseignant.","Le metteur en scène : utiliser différentes formes spatiales (ligne, colonne, forme géométrique, lettre…), temporelles (unisson, répétition, canon) et des groupements variés (duos, trios…) adaptés aux intentions.","Le metteur en scène : construire des instants clés, des coups de projecteur pour centrer l’attention du spectateur.","Le metteur en scène : anticiper les changements de partenaire et la disposition du matériel.","Le spectateur : repérer et analyser la prestation du groupe à partir des critères simples (éléments constitutifs du numéro, niveau de difficulté réussi ou non, respect du thème)."]},"Danse":{"cp":3,"a":"Composer et présenter une chorégraphie collective structurée en enrichissant des formes corporelles et des gestes simples, en jouant sur les composantes du mouvement : l’espace, le temps et l’énergie. Maîtriser ses émotions et accepter le regard des autres. Observer avec attention et apprécier avec respect les prestations.","p":["Mémoriser les différentes formes corporelles à reproduire.","Entrer en relation ou en contact simple avec ses partenaires (mains, buste, regard).","Espace : construire et reproduire des trajets moteurs précis.","Espace : s’orienter dans l’espace avec ses partenaires par rapport au spectateur.","Espace : se déplacer en exploitant : les directions, les plans, les volumes en contraste (avant/arrière, haut/bas, gauche/droite).","Temps : coordonner son action avec celles des autres (à l’unisson, en cascade, en canon).","Temps : utiliser des tempi (vitesse) différents (lent, rapide).","Temps : agir en concordance avec les traits dominants du monde sonore.","Energie : jouer avec les différentes qualités du mouvement (saccadé, continu, fort, faible, gestes explosifs).","Energie : doser son énergie et son tonus musculaire tout au long de sa danse."],"r":["Le chorégraphe : créer dans le cadre de composition proposé par l’enseignant.","Le chorégraphe : entrer dans un projet de création à partir d’un inducteur (le sport, les animaux, les sentiments, l’eau, le feu) en utilisant son imagination pour la transformer en forme corporelle.","Le chorégraphe : repérer les temps musicaux dominants.","Le spectateur : repérer et analyser la prestation individuelle et collective à partir de critères simples (concentration, composition, originalité)."]},"Basket-ball":{"cp":4,"a":"Dans un jeu à effectif réduit, rechercher le gain du match par des choix pertinents d’actions de passe ou dribble pour accéder régulièrement à la zone de marque et tirer en position favorable, face à une défense qui cherche à gêner la progression adverse dans le respect du non contact. S’inscrire dans le cadre d’un projet de jeu simple lié à la progression de la balle. Respecter les partenaires, les adversaires et les décisions de l’arbitre.","p":["S’informer avant d’agir : se situer sur le terrain, percevoir les partenaires (PB, NPB disponibles, à distance de passe), les adversaires, les espaces libres et la cible","Se reconnaître attaquant ou défenseur et réagir rapidement au changement de statut","Gérer son effort pour réaliser plusieurs matchs de 5 minutes sans perte d’efficacité","Le PB : choisir, en fonction de la position du défenseur proche et de sa position sur le terrain, de partir seul en progression ou d’échanger avec un partenaire ou encore de tirer.","Le PB : enchaîner les actions de dribble de progression, de tir et de passe sans pression défensive forte.","Le PB : maîtriser les arrêts et le pied de pivot.","Le PB : effectuer un tir fiable à l’arrêt ou après un double pas près de la cible.","Le PB : a l’arrêt, tenir la balle à 2 mains, armé haut.","Le PB : chercher à conserver la balle après un tir : rebond offensif.","Le NPB : se mettre à distance de passe (en fonction du PB et de ses capacités) pour lui offrir des solutions de passes en appui ou en soutien.","Le NPB : rompre l’alignement porteur – défenseur – non porteur.","Le NPB : enchaîner un déplacement vers l’avant après un échange réussi.","En défense : contrôler son engagement tout en cherchant à intercepter ou arrêter la progression du PB.","En défense : se replacer entre le PB et le panier.","En défense : chercher à récupérer la balle après un tir : rebond défensif."],"r":["L’observateur : relever des résultats d’actions fiables liés aux pertes de balle et conditions de tir.","L’observateur : evaluer de façon chiffrée l’efficacité d’une équipe en établissant des rapports entre les données recueillies (% de pertes de balles, % d’accès à la cible et de tirs en position favorable).","L’observateur : communiquer les résultats des observations pour aider à la formalisation d’un projet de jeu simple en attaque."]},"Football":{"cp":4,"a":"Dans un jeu collectif à effectif réduit, rechercher le gain du match par des choix pertinents d’actions de passe ou dribble supposant une maîtrise suffisante du ballon pour accéder régulièrement à la zone de marque et tirer en position favorable, face à une défense qui cherche à gêner la progression adverse. S’inscrire dans le cadre d’un projet de jeu simple lié à la progression du ballon. Respecter les partenaires, les adversaires et les décisions de l’arbitre.","p":["S’informer avant d’agir : se situer sur le terrain, percevoir les partenaires (PB, NPB disponibles, à distance de passe), les adversaires, les espaces libres et la cible.","Se reconnaître attaquant ou défenseur et réagir rapidement au changement de statut.","Gérer son effort pour réaliser plusieurs matchs de 5 minutes sans perte d’efficacité.","Le PB : identifier sa position par rapport à la position de l’adversaire direct, au couloir de jeu direct et sa distance avec le but pour décider : de progresser balle au pied, de passer à un partenaire mieux placé, d’effectuer un tir cadré.","Le PB : coordonner des actions de contrôle, de conduite de ballon, de passe et de tir.","Le PB : réaliser des équilibres unipodaux par des transferts d’appuis rapides, des dissociations d’actions pour : contrôler, conduire, dribbler, passer, tirer.","Le NPB : s’écarter et se démarquer à distance de passe en appui visible ou sur le côté du porteur de balle.","Le NPB : se placer sur la trajectoire du ballon afin de le contrôler.","Le NPB : rompre l’alignement porteur – défenseur – non porteur.","Le NPB : enchaîner un déplacement vers l’avant après un échange réussi.","En défense : identifier les pertes de balle de l’équipe et réagir en fonction de sa position sur le terrain.","En défense : contrôler son engagement tout en cherchant à gêner la progression adverse du ballon en se plaçant entre son but et le PB.","En défense : intercepter la transmission du ballon en se positionnant sur les lignes de passes adverses."],"r":["L’observateur : relever des résultats d’actions fiables liés aux pertes de balle et conditions de tir.","L’observateur : evaluer de façon chiffrée l’efficacité d’une équipe en établissant des rapports entre les données recueillies (% de pertes de balles, % d’accès à la cible et de tirs en position favorable).","L’observateur : communiquer les résultats des observations pour aider à la formalisation d’un projet de jeu simple en attaque."]},"Handball":{"cp":4,"a":"Dans un jeu à effectif réduit, rechercher le gain du match par des choix pertinents d’actions de passe ou dribble pour accéder régulièrement à la zone de marque et tirer en position favorable, face à une défense qui cherche à gêner la progression adverse. S’inscrire dans le cadre d’un projet de jeu simple lié à la progression de la balle. Respecter les partenaires, les adversaires et les décisions de l’arbitre.","p":["Se reconnaitre attaquant ou défenseur et réagir rapidement au changement de statut","Gérer son effort pour réaliser plusieurs matchs de 6 à 7 minutes sans perte d’efficacité En attaque","S’informer avant d’agir : percevoir les partenaires (PB, NPB démarqués, à distance de passe vers l’avant), les adversaires et le couloir de jeu direct permettant d’accéder à la zone favorable de tir","Faire des choix pertinents d’actions pour atteindre la cible, en tant que PB : dribbler pour avancer ou donner à un NPB libre vers l’avant, tirer en étant seul devant le gardien en zone favorable","NPB : se démarquer en avant à distance de passe ou se rapprocher du porteur pour l’aider à conserver la balle","Enchaîner et coordonner des actions motrices : réceptionner (à deux mains) et passer (à rebond ou tendue), à l’arrêt et en courant, à une distance optimale.","Enchaîner et coordonner des actions motrices : dribbler sans perdre la balle en progression vers la cible.","Enchaîner et coordonner des actions motrices : enchaîner un dribble, trois ou quatre appuis et un tir.","Enchaîner et coordonner des actions motrices : réceptionner/ tirer en appui, en mouvement ou en suspension en zone favorable. En défense","Percevoir les actions de l’adversaire et se placer entre le PB et le but à défendre.","Faire des choix pertinents d’actions dans l’intention de récupérer la balle et/ou empêcher sa progression et/ou l’intercepter : gêner le PB en respectant les règles ou marquer un NPB en gardant une vision périphérique sur la balle."],"r":["L’observateur : relever des résultats d’actions fiables liés aux pertes de balle et conditions de tir.","L’observateur : evaluer de façon chiffrée l’efficacité d’une équipe en établissant des rapports entre les données recueillies (% de pertes de balles, % d’accès à la cible et de tirs en position favorable).","L’observateur : communiquer les résultats des observations pour aider à la formalisation d’un projet de jeu simple en attaque."]},"Rugby":{"cp":4,"a":"Dans un jeu à effectif réduit et sur un terrain de largeur limitée, rechercher le gain d’un match par des choix pertinents permettant de conserver et de faire avancer le ballon jusqu’à l’en-but adverse face à une défense qui cherche à freiner ou bloquer la progression. S’inscrire dans le cadre d’un projet de jeu simple lié à la progression du ballon. Respecter les partenaires, les adversaires et les décisions de l’arbitre.","p":["S’informer avant d’agir : se situer sur le terrain, percevoir les partenaires (PB, NPB disponibles, à distance de passe), les adversaires, les espaces libres et l’en-but adverse.","Changer rapidement de statut et se reconnaître défenseur.","Gérer son effort pour réaliser plusieurs matchs de 6 à 8 minutes sans perte d’efficacité.","En attaque : enchaîner quelques actions fondamentales (donner, arracher, pousser, ramasser, esquiver) en les orientant en direction de l’en-but adverse.","En attaque : s’organiser pour percuter de profil en protégeant à la fois son corps et le ballon.","En attaque : ne pas s’isoler des partenaires afin de trouver le soutien nécessaire lorsque la progression individuelle n’est plus possible.","En attaque : assurer la conservation de la balle lors des phases de blocage en orientant ses actions vers son camp et en faisant obstacle avec son corps.","En attaque : offrir un soutien proche et essentiellement axial pour pousser ou relayer le PB.","En défense : constituer un rideau défensif à distance réglementaire de charge à chaque arrêt de jeu.","En défense : s’organiser individuellement pour attraper et ceinturer le PB afin de le freiner, le bloquer, le repousser ou l’amener au sol.","En défense : soutenir l’action défensive d’un partenaire pour en augmenter l’efficacité."],"r":["L’observateur : relever des résultats d’actions fiables liés aux pertes de balle et aux conditions d’essais.","L’observateur : evaluer de façon chiffrée l’efficacité d’une équipe en établissant des rapports entre les données recueillies (% de pertes de balles, % d’accès à l’en-but adverse).","L’observateur : communiquer les résultats des observations pour aider à la formalisation d’un projet de jeu simple en attaque."]},"Volley-ball":{"cp":4,"a":"Dans un jeu à effectif réduit, rechercher le gain du match par le renvoi de la balle, seul ou à l’aide d’un partenaire, depuis son espace favorable de marque en exploitant la profondeur du terrain adverse. S’inscrire dans le cadre d’un projet de jeu simple lié au renvoi de la balle. Respecter les partenaires, les adversaires et les décisions de l’arbitre.","p":["Différencier les balles qui donnent du temps à son partenaire de celles qui mettent l’adversaire en crise de temps.","En fonction de son ordre d’intervention (1er ou 2ème à toucher le ballon), différencier son rôle (réceptionneur, relayeur, attaquant) et les actions à accomplir en conséquence : conserver pour monter une balle haute en zone avant sur son partenaire si le joueur est en zone arrière.","En fonction de son ordre d’intervention (1er ou 2ème à toucher le ballon), différencier son rôle (réceptionneur, relayeur, attaquant) et les actions à accomplir en conséquence : renvoyer si le joueur est placé en zone avant et si le contexte est favorable en jouant dans la profondeur du terrain adverse.","En fonction de son ordre d’intervention (1er ou 2ème à toucher le ballon), différencier son rôle (réceptionneur, relayeur, attaquant) et les actions à accomplir en conséquence : renvoyer le ballon dans le camp adverse si le joueur est dans l’espace favorable de marque en jouant dans la profondeur du terrain adverse.","En fonction de son ordre d’intervention (1er ou 2ème à toucher le ballon), différencier son rôle (réceptionneur, relayeur, attaquant) et les actions à accomplir en conséquence : conserver pour monter une balle haute en zone avant sur son partenaire s’il ne peut marquer le point directement.","Se déplacer pour jouer le ballon équilibré et choisir un mode d’intervention adapté.","Orienter ses appuis et ses surfaces de frappe vers la zone à atteindre.","Sortir de l’alignement avec son partenaire pour faciliter le relais, le soutien et/ou le renvoi dans le camp adverse.","Communiquer pour s’identifier intervenant sur la balle.","S’organiser pour occuper seul ou à deux l’espace de jeu."],"r":["L’observateur : Repérer des résultats d’actions fiables liés aux pertes de balles et aux conditions de marque.","L’observateur : Evaluer de façon chiffrée l’efficacité d’une équipe en établissant des rapports entre les données recueillies (% de pertes de balles, % de points gagnés depuis et dans les zones avant et arrière).","L’observateur : Communiquer les résultats des observations pour aider à la formalisation d’un projet de jeu simple en attaque."]},"Badminton":{"cp":4,"a":"En simple, rechercher le gain loyal d’une rencontre en choisissant entre renvoi sécuritaire et recherche de rupture sur des volants favorables par l’utilisation de frappes variées en longueur ou en largeur. Assurer le comptage des points et remplir une feuille d’observation.","p":["Servir de façon réglementaire (volant frappé en dessous de la dernière côte, un seul essai si le geste a commencé, dans la diagonale opposée, en appuis sur les deux pieds).","Reconnaître une situation favorable pour soi et une situation de « crise de temps » chez l’adversaire (non replacé au centre et encore en mouvement au moment de la frappe) et l’utiliser pour rompre l’échange.","Déplacer son adversaire par une succession de frappes variées en longueur ou en largeur.","Repérer la position de l’adversaire sur le terrain et viser un espace libre en privilégiant les zones qui mettent en difficulté.","Garder la raquette haute tout au long de l’échange en prise universelle.","Décaler les appuis et les épaules en gardant le coude haut pour augmenter la vitesse de la raquette à l’impact.","Frapper le volant au dessus de la tête.","Adopter une posture dynamique au moment de la frappe de l’adversaire pour amorcer plus rapidement un déplacement.","Se déplacer rapidement en fonction de la trajectoire du volant pour frapper équilibré et se replacer immédiatement après avoir été débordé.","Doser l’accélération en fonction du type de frappe (geste accéléré pour un dégagement, bloqué pour un amorti) et passer de l’action « pousser » à l’action « fouetter »."],"r":["L’arbitre : identifier le changement de service et les principales fautes.","L’arbitre : compter les points et annoncer le score du serveur en premier.","L’observateur : identifier, pour le camarade observé, les situations favorables et leur exploitation."]},"Tennis de table":{"cp":4,"a":"En simple, rechercher le gain loyal d’une rencontre en assurant la continuité de l’échange, en coup droit ou en revers et en profitant d’une situation favorable pour le rompre par une balle placée latéralement ou accélérée. Assurer le comptage des points et remplir une feuille d’observation.","p":["Servir de façon réglementaire (présenter et lancer la balle, contact balle- raquette en arrière de la table, premier rebond sur sa demi-table).","Repérer la situation favorable (balle « donnée » et/ou adversaire décalé pour le déborder).","Orienter les surfaces de frappe pour atteindre différentes cibles latérales en coup droit ou en revers et produire des trajectoires tendues.","Jouer en plaçant sa balle pour éviter la zone centrale de la demi-table adverse.","Accélérer une frappe sur une balle favorable.","Prendre la balle au sommet de la trajectoire pour la frapper en adaptant l’inclinaison de la raquette et l’orientation du geste.","Adopter une posture dynamique pour réagir rapidement et se mettre à distance de frappe.","Doser l’énergie lors du contact balle/raquette et passer de l’action « pousser » à l’action « frapper »."],"r":["L’arbitre : compter les points et annoncer le score du serveur en premier.","L’observateur : identifier, pour le camarade observé, les situations favorables et leur exploitation.","L’observateur : remplir une fiche de score."]},"Boxe française":{"cp":4,"a":"S’engager loyalement dans un assaut, en rechercher le gain tout en contrôlant ses touches et en maîtrisant la distance pour toucher sans être touché. Assurer le comptage des points et le respect des règles de sécurité.","p":["Dissocier l’action des membres supérieurs et inférieurs","Prendre des repères pour construire la distance de touche (je suis près je touche en poings, je suis loin je touche en pieds)","Se déplacer pour se placer à distance de touche","Réaliser une touche réglementaire sans risque pour l’adversaire : armer, trajectoire, contrôle de la puissance","En défense : Adopter la position de garde de référence : appuis au sol pieds décalés, poings écartés à hauteur des mâchoires, coudes au contact du buste","En défense : Maintenir sa garde en déplacement","En défense : Utiliser préférentiellement certaines parades (protection, bloquées, chassées) ou des esquives (totales ou partielles) pour ne pas être touché"],"r":["L’arbitre : appliquer le protocole et les commandements","L’arbitre : se placer perpendiculairement au couple des tireurs pour pouvoir identifier et sanctionner les éventuelles fautes","L’arbitre : intervenir de façon opportune et affirmée pour permettre une pratique sécuritaire des tireurs en sanctionnant : une touche non contrôlée, une trajectoire verticale montante ou descendante, une arme autre que les extrémités segmentaires codifiées, une cible interdite et une sortie volontaire de l’enceinte","L’arbitre : s’exprimer avec les termes appropriés aux actions reconnues pendant l’assaut","Le juge : identifier et compter les touches en poings ou pieds pour un tireur","Le juge : comptabiliser de façon fiable les touches valides des touches non valides (non réglementaires, dans le vide, sur les avant-bras ou les gants)"]},"Lutte":{"cp":4,"a":"S’engager loyalement et en toute sécurité dans un combat, en rechercher le gain par l’utilisation de contrôles et formes de corps sur un adversaire gardant ses appuis au sol. Assurer le comptage des points et le respect des règles de sécurité.","p":["Savoir chuter et faire chuter sans risque sur des décalages (sans projection), dans des directions différentes en construisant un équilibre du couple « attaquant /attaqué » pendant la chute jusqu’au sol.","Apprécier les distances.","En attaque : réduire la distance d’affrontement pour agir efficacement sur le corps de l’adversaire.","En attaque : réaliser des contrôles simples sur le corps de l’adversaire au sol ou debout.","En attaque : peser et fixer les appuis de l’adversaire pour le retourner au sol ou le renverser debout.","En attaque : combiner des forces pour réaliser un retournement au sol ou un décalage debout.","En attaque : au sol réaliser des retournements dans l’axe longitudinal de l’adversaire.","En attaque : debout à partir d’un contrôle, réaliser des décalages avants, latéraux et en rotation sur un déséquilibre en fonction de l’attitude donnée par l’adversaire.","En attaque : contrôler et maintenir son adversaire sur le dos pour le tombé.","En défense : se sentir en position de mise en danger ou de tombé.","En défense : se défendre en se libérant du contrôle adverse et en revenant à plat ventre."],"r":["L’arbitre : appliquer le protocole et les commandements.","L’arbitre : se déplacer avec les lutteurs, réagir, parler fort pour diriger le combat.","L’arbitre : intervenir de façon opportune et affirmée pour permettre une pratique sécuritaire en se positionnant pour empêcher les sorties de zones, les actions dangereuses et prises interdites.","Le juge : identifier les prises contrôlées, le tombé, la mise en danger, le passage arrière.","Le juge : mettre en relation les informations recueillies et les cotations simplifiées.","Le juge : seconder l’arbitre dans ses prises de décision."]}},"N2":{"Demi-fond":{"cp":1,"a":"Réaliser la meilleure performance possible sur un temps de course de 12 à 15 minutes, fractionné en 3 à 4 périodes séparées de temps de récupération compatibles avec l’effort aérobie, en maîtrisant différentes allures très proches de sa VMA et en utilisant principalement des repères sur soi et quelques repères extérieurs. Etablir un projet de performance et le réussir à 0,5 Km/h près.","p":["Elaborer un projet d’allures différentes et adaptées sur 3 ou 4 périodes en tenant compte du volume total des courses, de la récupération et de sa VMA.","Exploiter sa puissance aérobie pour réaliser la meilleure performance","Adopter une attitude de course économique, stabilisée et adaptée aux allures de course envisagées.","Adopter un rythme respiratoire maîtrisé, régulier et adapté à des efforts proches de sa VMA.","Adopter et maintenir des allures de courses proches de sa VMA à 0,5 km/h et les réguler essentiellement à l’aide des repères internes.","Optimiser les temps courts de récupération en restant actif.","Interpréter ses résultats en tenant compte des informations externes après chaque course pour affiner son projet."],"r":["Chronométrer en prenant ou donnant des temps intermédiaires.","Communiquer et interpréter des informations fiables pour aider un camarade dans la définition de son projet."]},"Course de haies":{"cp":1,"a":"A partir d’un départ commandé réaliser la meilleure performance possible sur une distance de 40 à 60 mètres, avec 4 ou 5 haies de 70 à 84 centimètres de haut, en élevant le moins possible son centre de gravité et en réalisant 4 appuis dans l’intervalle le plus adapté à ses possibilités. Assurer le recueil de données fiables. Construire et apprécier l’efficacité de ses actions à partir de repères sur soi et d’observations extérieures.","p":["Exploiter les ressources de la filière anaérobie alactique.","Utiliser et mobiliser ses ressources neuromusculaires pour une vitesse de réaction et vitesse gestuelle maximales.","Adopter une position de départ en fonction de son pied d’appel et du nombre d’appuis à réaliser avant la première haie.","Attaquer loin de la haie, genou haut dans l’axe,","Dissocier l’action des deux jambes sur la haie pour favoriser une reprise active au sol de la jambe d’attaque.","Utiliser de façon dynamique l’action des bras et la coordonner avec celle des jambes pour rester équilibré.","Maintenir une foulée efficace et régulière dans l’intervalle en intégrant un rythme rapide.","Choisir le parcours et l’intervalle permettant de réaliser 4 appuis sur toute la distance, en comparant avec méthode les résultats transmis et les sensations éprouvées."],"r":["Donner les ordres en tant que starter et s’assurer du respect de ces commandements par les coureurs.","Etablir une communication entre le starter et le chronométreur.","Chronométrer de façon précise (mesure régulière et vérifiée à 1/10ème près).","Repérer et observer les actions réalisées à l’impulsion, au franchissement et dans la course inter obstacles.","Communiquer et interpréter des informations fiables pour aider un camarade à améliorer sa performance."]},"Saut en hauteur":{"cp":1,"a":"A partir d’un élan étalonné et accéléré de 6 à 8 appuis, réaliser la meilleure performance possible, avec un nombre limité d’essais, en utilisant un franchissement dorsal de la barre en son milieu. Assumer dans un groupe restreint les rôles d’observateur et de juge.","p":["Avoir une course d’élan rectiligne puis curviligne.","Adopter une attitude de course haute et rythmée dans la partie curviligne de l’élan.","Prendre l’impulsion au niveau du premier tiers du tapis de chute.","Reproduire, d’un essai à l’autre, le même type de course au niveau de l’amplitude et de la fréquence.","Se grandir à l’impulsion, rester gainé.","Utiliser les membres libres : action des bras et de la jambe libre pour alléger le corps (genou libre qui rentre vers l’intérieur et action dissociée bras gauche et bras droit).","Différencier et dissocier dans le franchissement train supérieur et train inférieur.","Chuter sur les épaules.","Gérer le nombre d’essais autorisé : décider du début de son concours et des hauteurs à franchir."],"r":["Repérer et observer les caractéristiques de la course d’élan, du franchissement et de la réception.","Mesurer de façon règlementaire avec le matériel appropriée.","Juger la validité réglementaire d’un saut.","Communiquer et interpréter des informations fiables à un camarade pour optimiser sa performance."]},"Lancer de javelot":{"cp":1,"a":"Réaliser la meilleure performance possible avec un nombre limité d’essais en enchaînant, sans rupture, prise d’élan et phase finale de double appui. Construire et réguler l’efficacité de ses actions à partir de repères sur soi et d’observations extérieures.","p":["Prendre des informations visuelles et proprioceptives (vissage, dévissage, relâchement, grandissement).","Se placer de profil pendant la phase de pas chassés et/ ou de pas croisés.","Faire prendre de l’avance aux appuis pendant cette même phase.","Dissocier le haut et le bas du corps (vissage, dévissage).","Faire « face en avant » puis lancer.","Accélérer le geste au moment du lancer, finir « grand », orienté vers l’avant.","Etalonner sa course d’élan avec des repères intermédiaires pour rester équilibré, ne pas piétiner, ne pas dépasser la limite.","Mettre en relation les performances, les trajectoires réalisées et les observations transmises avec l’analyse de sa propre activité. Corriger lors des essais suivants.","Stabiliser une zone de performance maximale optimisant son potentiel du moment.","Gérer le nombre limité d’essais en fonction des performances réalisées.","Optimiser les temps de récupération en restant actif."],"r":["Mesurer règlementairement et avec rigueur.","Repérer et observer la prise d’avance des appuis et la continuité des actions lors de la prise d’élan.","Communiquer et interpréter des informations fiables pour aider un camarade à améliorer sa performance."]},"Multibond":{"cp":1,"a":"A partir d’un élan étalonné et accéléré de 8 à 12 appuis, rechercher la meilleure performance possible sur 3 à 5 bonds en conservant la vitesse et en maitrisant l’amplitude et la hauteur des bonds. Assumer dans un groupe restreint les rôles d’observateur et de juge.","p":["Réaliser une course d’élan accélérée, précise, articulant prise de vitesse et préparation au saut dans les derniers appuis.","Reproduire de façon stable une course d’élan étalonnée à partir de foulées constantes. (C3)","Augmenter la fréquence des appuis à la fin de sa course d’élan.","Maîtriser la hauteur et la longueur de ses bonds (et surtout du premier) pour conserver au mieux sa vitesse.","Rechercher la meilleure performance totale du multi bond par le meilleur équilibre dans la longueur des bonds. (C7)","Chercher à accélérer son pied au sol.","Augmenter les temps de suspensions et réduire les temps d’appuis.","Améliorer l’utilisation des segments libres pour rester équilibré, optimiser ses bonds et conserver sa vitesse.","Intérioriser le rythme des impulsions."],"r":["Repérer la répartition des différents bonds dans l’espace, un changement de rythme dans les appuis (en situation ou en vidéo), une variation de vitesse.","Mesurer de façon règlementaire avec le matériel appropriée.","Juger la validité réglementaire d’un saut.","Communiquer et interpréter des informations fiables à un camarade pour optimiser sa performance."]},"Relais-vitesse":{"cp":1,"a":"A partir d’un départ commandé réaliser la meilleure performance possible dans un relais de 2 à 4 x 40 à 50 mètres, en ajustant les vitesses et en utilisant l’élan autorisé pour une transmission du témoin dans la zone réglementaire. Elaborer avec ses coéquipiers un projet tactique. Assumer au sein d’un groupe restreint les rôles d’observateur, de starter, de juge et de chronométreur.","p":["Définir collectivement un projet tactique permettant d’obtenir la meilleure performance de relais en fonction des ressources physiologiques et techniques de chacun.","Enchaîner des efforts de type anaérobie alactique en veillant à récupérer de façon suffisante.","Etablir et conserver un alignement général du corps par rapport aux forces propulsives.","Maîtriser la direction de sa course en virage dans son couloir et conserver un équilibre général.","Adopter le meilleur rapport amplitude fréquence des foulées pour augmenter et conserver sa vitesse maximale","Exploiter la zone d’élan pour ajuster les vitesses des coureurs et recevoir le témoin à pleine vitesse.","Pour le premier relayeur, réaliser un départ de sprint en réaction à des commandements du starter.","Identifier durant la course le moment propice pour donner le signal de transmission dans la zone.","Coordonner distinctement les actions de courir – donner le signal - identifier la position de main du receveur – transmettre le témoin.","Réaliser un départ débout en adoptant une position optimale dans le couloir pour réagir rapidement à un signal visuel (passage du partenaire sur la marque).","Réagir rapidement à un signal verbal pour présenter sa main receveuse selon la technique retenue.","Conserver une dissociation segmentaire du bras libre et du bras receveur pendant la phase de transmission."],"r":["Donner les ordres en tant que starter et s’assurer du respect de ces commandements par les coureurs.","Chronométrer de façon précise (mesure régulière et vérifiée à 1/10ème près).","Etablir une communication entre le starter et le chronométreur.","Juger la validité réglementaire d’un relais.","Communiquer et interpréter des informations fiables pour analyser ensemble l’efficacité du projet collectif."]},"Natation longue":{"cp":1,"a":"A partir d’un départ commandé, réaliser sur une durée de 12 minutes, la meilleure performance possible principalement en crawl en tirant bénéfice des virages et en recherchant l’amplitude de nage. Elaborer un projet d’action par rapport aux modes de nage, l’annoncer et le mettre en œuvre. Assumer au sein d’un groupe restreint les rôles de starter et de chronométreur.","p":["Créer et conserver un équilibre hydrodynamique favorable à la glisse au départ, pendant les déplacements et la reprise de nage.","Respirer de façon adaptée : en recherchant l’augmentation du débit expiratoire et sa continuité.","Respirer de façon adaptée : en inspirant rapidement en fin de trajet moteur.","Accorder une importance au temps de glisse pendant la nage (phase de glisse et prise d’appui).","Augmenter l’amplitude de nage : entrer loin devant, allonger le temps de prise d’appui et de poussée.","Optimiser le virage : conserver sa vitesse à l’approche du mur.","Optimiser le virage : effectuer une poussée axée et puissante sur le mur (appui solide) pour créer la plus grande vitesse possible.","Adopter une posture aussi profilée que possible lors de la coulée","Identifier la profondeur optimale pour la réalisation des coulées et le temps optimal pour effectuer la reprise de nage.","S’informer (repères extéroceptifs et proprioceptifs) pour gérer son allure et son effort.","Construire un projet d’action permettant d’utiliser au mieux ses possibilités."],"r":["Le starter / juge : donner un départ de façon claire et intelligible.","Le starter / juge : organiser les rôles pour que chaque membre du groupe puisse réaliser sa meilleure performance possible dans le temps et l’espace imparti.","Le starter / juge : repérer le non respect des nages codifiées et des virages.","L’observateur / chronométreur : chronométrer au 1/10ème près, prendre des temps intermédiaires et en informer régulièrement son nageur.","L’observateur / chronométreur : identifier les critères en responsabilité : distance parcourue, nombre de 25m en crawl, amplitude des trajets moteurs, efficacité du plongeon, des virages."]},"Natation de vitesse":{"cp":1,"a":"A partir d’un départ commandé, réaliser la meilleure performance possible sur une distance de 50 mètres selon 2 modes de nage, ventral et dorsal, en optimisant le plongeon, le virage et le rapport amplitude fréquence. Assumer au sein d’un groupe restreint les rôles de starter et de chronométreur.","p":["Maîtriser une technique de départ plongé permettant une coulée optimale par un corps profilé, une vitesse subaquatique importante, une remontée lointaine et rapide, une reprise de nage dès que la vitesse décroît.","Sur les 2 nages, gagner en amplitude par un roulis de la ceinture scapulaire sans provoquer des mouvements de tangage ou de lacet.","Augmenter, dans les 2 nages, la qualité des appuis pendant la phase propulsive des bras en différenciant les actions de tirer / pousser et en accélérant constamment le trajet","Adopter et conserver une fréquence compatible avec la durée de l’épreuve.","Réaliser une expiration active et complète et placer une inspiration brève à la fin des actions propulsives des bras.","Maintenir son organisation respiratoire (sur 2, 3 ou 4 CB) et propulsive malgré l’intensité de l’effort.","Créer un temps fort pour virer : repérer la zone de virage sans ralentir (5m), se retourner par une des techniques (virage appui ou virage culbute) sans perdre de temps, effectuer une poussée complète sur un corps profilé, s’organiser dans la coulée pour le changement de nage, reprendre la nage dès la perte de vitesse.","S’informer tout en se déplaçant à partir de repères situés au fond du bassin et sur les lignes d’eau.","Choisir en fonction de ses ressources l’alternance des nages, le rapport amplitude/fréquence, l’organisation respiratoire.","Gérer son énergie pour optimiser les deux 25m."],"r":["Le starter / juge : donner un départ de façon claire et intelligible.","Le starter / juge : repérer le non respect des nages codifiées et des virages.","Le starter / juge : organiser les rôles pour que chaque membre du groupe puisse réaliser sa meilleure performance possible dans le temps et l’espace imparti.","L’observateur / chronométreur : chronométrer au 1/10ème près, prendre un temps intermédiaire.","L’observateur / chronométreur : identifier les critères en responsabilité : plongeon, virage, nombre de CB sur chaque 25m, temps de prise d’air."]},"Canoë-kayak":{"cp":2,"a":"Choisir et conduire un déplacement avec précision en composant avec la force des éléments naturels. Adopter des attitudes d’entraide et de sécurité lors d’un dessalage. Reconnaître les caractéristiques du milieu de navigation.","p":["Naviguer sur des parcours d’eau vive classe 1 (passage 2) ou d’eau calme richement aménagés ou sur mer (maximum vent 3 beaufort).","Choisir en conséquence son équipement personnel et le régler.","Observer les zones de navigation, choisir et réaliser un parcours en fonction de ses capacités.","Anticiper les effets du courant et/ou du vent sur la trajectoire du bateau et composer son énergie aux forces extérieures, voire naviguer par détour.","Utiliser la gîte pour minimiser les effets du courant (réel ou vitesse) sur la coque et maintenir l’équilibre de l’embarcation.","Utiliser éventuellement la carène de son bateau pour le faire changer de direction.","Coordonner ses actions et l’utilisation de la pagaie pour aller vite, pour tourner, pour s’équilibrer.","Freiner ou doser des coups de pagaie afin de se maintenir sur place face au courant ou au vent.","Utiliser des réchappes (gîte sur cravate, appuis équilibrateurs)","Réembarquer seul dans son embarcation en eau profonde en s’appuyant sur une autre embarcation.","Dans des rapides classe 1-2, nager en position de sécurité et rejoindre le bord."],"r":["Intervenir à bon escient en cas de dessalage d’un camarade","Récupérer la pagaie d’un camarade dessalé et la rapporter au bord.","Sur l’eau, vider un bateau plein d’eau à plusieurs. De l’observateur","Identifier la pertinence et l’efficacité du projet d’action d’un camarade à partir du relevé de données, de ses points forts et des points faibles."]},"Course d’orientation":{"cp":2,"a":"milieu délimité plus ou moins connu. Gérer les efforts en adoptant des allures de course optimales en rapport au milieu et au moment du déplacement. Respecter les règles de sécurité et l’environnement.","p":["Associer les informations relatives au terrain (planimétrie, hydrographie, relief, végétation) à des efforts physiques et des motricités particulières.","Elaborer un projet de déplacement, sélectionner et anticiper les éléments à suivre et adapter son allure en fonction de ses capacités et des particularités du terrain pour gagner en efficacité : courir vite sur des segments d’itinéraire faciles ; ralentir et récupérer aux points de décision et à l’attaque d’un poste.","Solliciter et mobiliser ses ressources « aérobie » pour réaliser le déplacement le plus rapide possible.","Mémoriser son itinéraire d’un poste à l’autre.","Choisir et suivre des lignes complexes pour se rendre au poste.","Elaborer une ligne d’arrêt, un point d’attaque de poste.","Attaquer et sortir d’un poste placé à proximité de lignes directrices.","Reconnaître la qualité du terrain pour adapter sa motricité, sa foulée, la qualité des appuis.","Contourner un obstacle (étang, forêt dense) sans perdre sa direction.","Réaliser quelques « sauts » entre des lignes proches.","Vérifier régulièrement son itinéraire en utilisant des points d’appui et se recaler si nécessaire."],"r":["Poser et contrôler un poste","Renseigner l’ensemble du carton de contrôle","Retracer son itinéraire effectif sur la carte","Calculer et analyser le temps réalisé à partir d’une heure de départ et d’une heure d’arrivée, les temps des circuits entre les balises en fonction de ses choix et de sa vitesse de course","Commenter et analyser son itinéraire avec les autres."]},"Escalade":{"cp":2,"a":"Choisir et conduire un déplacement pour grimper en moulinette et enchaîner deux voies différentes proches de son meilleur niveau, en optimisant les prises de mains et de pieds et en combinant efficacement la poussée des jambes et la traction des bras. Assurer un partenaire en toute sécurité.","p":["Concevoir un projet de grimpe pour enchaîner deux voies en fonction de ses ressources.","Réguler si besoin son projet entre la première et deuxième voie.","Identifier les passages difficiles ou faciles d’une voie.","Identifier et mémoriser les prises utilisées, les mouvements réalisés, les PME utilisées lors d’essais précédents.","Mettre en relation les réalisations des autres grimpeurs avec ses propres techniques et mouvements réalisés.","Identifier et utiliser les prises de plus en plus éloignées de son axe de progression.","S’équilibrer pour se reposer et observer.","Connaître et utiliser les PME les plus adaptées en fonction des profils de voies (dalle, devers, dièdre, toit).","S’équilibrer en organisant son placement en fonction de l’orientation et du type de saisie de la prise pour se relâcher et observer la suite.","S’équilibrer pour progresser.","Coordonner plusieurs déplacements de pieds avec une même prise de main pour progresser avec plus d’amplitude et de dynamisme dans ses mouvements.","Enchaîner des actions en séquences mémorisées qui associent plusieurs déplacements segmentaires entre deux points de repos.","Créer des lignes d’appuis croisés (main/pied opposé) et des oppositions (pied/pied et main/pied) pour optimiser l’utilisation des prises.","Alterner les phases statiques d’équilibration et les phases dynamiques de déplacements pour optimiser ses performances.","Gérer ses ressources pour enchainer deux voies en s’économisant et en profitant des phases statiques d’équilibration, du temps de rappel et de ré-encordement pour récupérer en soufflant et en se relâchant.","Apprécier à partir du résultat transmis la justesse de ses choix et l’efficacité de ses actions.","Ranger ou lover une corde."],"r":["L’assureur : suivre et réguler la tension de la corde en fonction des variations de vitesse et des changements de direction du grimpeur.","L’assureur : conserver l’éventuel nœud « sonnette » en place sur une corde tendue tout au long de l’ascension du grimpeur.","L’assureur : réagir de manière rapide et efficace en situation difficile.","L’observateur : reconnaître les règles d’action liées à l’utilisation des PME et des appuis dynamiques de progression.","L’observateur : observer un grimpeur avec des critères objectifs permettant d’évaluer son efficacité pour l’aider à déterminer son projet de grimpe.","L’observateur : gérer le temps et l’espace accordés au groupe."]},"Aérobic":{"cp":3,"a":"Concevoir et présenter une routine collective, sur un support musical (de 120 à 140 BPM), comportant des éléments des différentes familles dont au moins un saut et utilisant des pas de base, associés à des mouvements de bras complexes ou dissociés. Juger les prestations à partir d’un code construit en commun.","p":["Gérer son effort, son tonus musculaire et l’intensité des mouvements.","Contrôler son équilibre corporel, le maintien de ses postures et ses déséquilibres.","Réaliser les pas de base spécifiques à l’activité avec amplitude et précision.","Réaliser trois ou quatre difficultés de différentes familles (dont un saut et une difficulté au sol) en respectant les exigences techniques minimales.","Coordonner le plus souvent possible des pas de base et des mouvements de bras complexes, asymétriques, associés à différentes formes de mains.","Evoluer sur des trajectoires directes ou indirectes, ordonnées ou désordonnées pour changer de formation (trois ou quatre formations).","Evoluer en synchronisme avec le rythme de la musique et ses partenaires (BPM de 120 à 140).","Mémoriser et réaliser des séquences imposées, semi créées et créées.","Reproduire des séquences chorégraphiées complexes dont une séquence « miroir » de difficulté supérieure.","Réaliser des transitions et des liaisons originales et/ou plus complexes."],"r":["Le chorégraphe : construire des phrases de pas sur huit temps.","Le chorégraphe : construire un bloc en trouvant un enchaînement logique de pas permettant de se déplacer.","Le chorégraphe : faire des choix de composition : chorégraphie, difficultés et formations.","Le chorégraphe : lier de façon originale la chorégraphie aux difficultés et agencer les différentes séquences.","Le juge : reconnaître et apprécier la valeur d’une routine en se référant à un code construit en commun.","Le juge : apprécier et juger la prestation du groupe en fonction des critères précis."]},"Acrosport":{"cp":3,"a":"Concevoir et présenter un enchaînement maîtrisé d’au moins 5 figures acrobatiques statiques et dynamiques, montées et démontées de façon active et sécurisée, où le voltigeur sera au moins une fois en situation de verticale renversée. Juger les prestations à partir d’un code construit en commun.","p":["Optimiser le rapport prise de risque/maîtrise dans la réalisation des figures au regard des possibilités de chacun.","Monter et démonter les figures de façon dynamique et originale.","Enchaîner les différentes figures acrobatiques statiques et dynamiques avec des éléments de liaison gymniques ou chorégraphiques.","Mémoriser sa prestation et coordonner ses actions avec celles des autres.","Gérer ses efforts tout au long de l’enchaînement.","Porteur : assurer ses prises sur le voltigeur.","Porteur : porter à toutes les hauteurs.","Porteur : accompagner le voltigeur dans les figures dynamiques.","Voltigeur : s’équilibrer et maintenir une posture gainée sur une base élevée.","Voltigeur : réduire les surfaces de contact avec le porteur.","Voltigeur : maîtriser une situation de verticale renversée : placement du bassin, gainage, alignement segmentaire.","Voltigeur : contrôler son élan pour ne pas perturber l’équilibre de la figure acrobatique.","Voltigeur : anticiper et organiser son espace de réception.","Aide : accompagner le voltigeur sans le lâcher jusqu’à son point d’arrêt, d’équilibre, de réception","Aide : anticiper les placements adéquats et les moments « risqués »."],"r":["Chorégraphe : choisir les figures acrobatiques et les éléments chorégraphiques permettant de dynamiser l’enchaînement.","Chorégraphe : lier de façon originale les figures choisies et organiser les relations entre les acrobates","Chorégraphe : corriger les gestes parasites.","Juge : apprécier la valeur des figures acrobatiques par rapport à leur difficulté et leur complexité pour les hiérarchiser dans un code commun.","Juge : reconnaître les éléments réalisés par rapport au code construit en commun.","Juge : repérer et apprécier les fautes d’exécution à partir d’indicateurs précis."]},"Gymnastique":{"cp":3,"a":"Dans le respect des règles de sécurité, concevoir et présenter un enchaînement maîtrisé d’éléments gymniques combinant les actions de « voler, tourner, se renverser ». Juger les prestations à partir d’un code construit en commun.","p":["Choisir les éléments gymniques adaptés à ses ressources en gérant de façon optimale le rapport difficulté/exécution.","Les combiner selon une logique d’enchaînement facilitant leur exécution et respectant les modalités de composition imposées.","Mémoriser son enchaînement.","Coordonner des actions motrices « tourner, voler, se renverser » et d’autres pour réaliser des éléments gymniques plus complexes avec et sans appuis manuels sur les agrès et au sol (salto avant, sortie rondade à la poutre).","Réaliser l’ATR ou des éléments acrobatiques exploitant la verticale renversée au sol et aux agrès (saut de main, lune).","Identifier les temps forts et faibles des actions motrices des éléments gymniques et de leur enchaînement.","Créer des élans en utilisant des appuis actifs et des suspensions actives et gainées.","Anticiper et alterner des phases de déplacements (acrobatie et élan) et des phases d’équilibrations (postures d’équilibre, de maintien ou de souplesse).","Enchaîner des éléments gymniques variés sans rupture, avec amplitude et correction en respectant l’alignement segmentaire.","Gérer son effort pour donner du rythme à sa prestation."],"r":["L’aide : apprécier la prestation d’un gymnaste pour le corriger à partir des critères de réalisation.","Le juge : apprécier la valeur des éléments gymniques par rapport à leur complexité pour les hiérarchiser dans un code commun.","Le juge : reconnaître les éléments réalisés par rapport au code construit en commun.","Le juge : repérer et apprécier les fautes d’exécution à partir d’indicateurs simples et précis."]},"Gymnastique rythmique":{"cp":3,"a":"Concevoir et présenter un enchaînement à visée artistique, en trio ou en quatuor, combinant des formes corporelles et des manipulations d’engins dans un espace organisé en relation avec une musique. Juger les prestations à partir d’un code construit en commun.","p":["Gérer son tonus musculaire : tension, relâchement.","Contrôler son équilibre corporel, le maintien de ses postures.","Varier l’énergie de ses mouvements.","Maîtriser au moins une difficulté corporelle dans chaque groupe (saut, pivot, équilibre, souplesse).","Combiner une difficulté corporelle avec une technique manipulatoire ou un élément de communication en lien avec le thème choisi.","Coordonner des actions de plus en plus précises et complexes avec une concordance corps/engin approfondie.","Investir l’espace de manière variée.","Réaliser plusieurs formations spatiales avec les partenaires et évoluer de l’une à l’autre.","Manipuler dans différents plans.","Coordonner ses actions avec celles de ses partenaires de manière synchronisée en succession rapide, en canon, en contraste.","Varier la richesse des échanges par transmission, lancer, rouler, ensemble ou en sous groupe, et jouer sur les modalités de lancer et de rattraper.","Agir en concordance avec les traits dominants du monde sonore."],"r":["Le chorégraphe : choisir et lier de façon originale les éléments corporels et manipulatoires, les relations, les échanges et les formations en fonction d’indices musicaux","Le chorégraphe : apprécier la valeur des éléments par rapport à leur difficulté et leur complexité pour les hiérarchiser dans un code commun.","Le chorégraphe : reconnaître les éléments réalisés par rapport au code construit en commun.","Le chorégraphe : repérer et apprécier les fautes d’exécution à partir d’indicateurs précis."]},"Arts du cirque":{"cp":3,"a":"Composer et présenter un numéro collectif s’inscrivant dans une démarche de création en choisissant des éléments dans les trois familles dont la mise en scène évoque un univers défini préalablement. Apprécier les prestations de façon argumentée à partir de quelques indicateurs simples.","p":["Diversifier et complexifier les formes techniques et corporelles dans les trois familles : en augmentant la précision, la hauteur, la vitesse, le nombre.","Diversifier et complexifier les formes techniques et corporelles dans les trois familles : en jouant sur la combinaison de 3 familles (chacune devenant le support des 2 autres).","Contrôler son équilibre et les différentes trajectoires sans voir, décentrer le regard en se construisant de nouvelles sensations kinesthésiques.","Gérer la prise de risque.","Eliminer pour choisir d’approfondir une technique dans chaque famille et ne retenir qu’une ou deux figures singulières, les plus difficiles possibles mais précises, maîtrisées, mémorisées.","Rechercher des appuis dans le public pour susciter des émotions et solliciter des applaudissements.","Fixer l’attention sur une image, un bruit et mobiliser différents registres corporels, sensoriels à cette intention.","Entrer et sortir de piste de manière inédite et/ou surprenante.","Mémoriser le déroulement du scénario sans s’appuyer sur un partenaire."],"r":["Le metteur en scène : suggérer et sélectionner les propositions en relation avec l’évocation de l’univers choisi et l’effet à produire sur le spectateur en jouant sur les formes, les types de relation, l’organisation de l’espace, les costumes, la musique, les silences, les zooms.","Le metteur en scène : organiser le scénario chronologique du numéro.","Le metteur en scène : mettre en place des codes, des signaux pour communiquer entre les différents acteurs.","Le spectateur : identifier le thème à partir du donné à voir, de l’impression.","Le spectateur : repérer les procédés de composition utilisés et les deux ou trois gestes, attitudes, instants clés du spectacle.","Le spectateur : apprécier la qualité d’interprétation individuelle et collective des acteurs: dextérité, degré de concentration.","Le spectateur : argumenter sur les effets ressentis.","Le spectateur : situer le niveau de difficulté d’une figure."]},"Danse":{"cp":3,"a":"Composer et présenter une chorégraphie collective en choisissant des procédés de composition et des formes corporelles variées et originales en relation avec le projet expressif. Apprécier les prestations de façon argumentée à partir de quelques indicateurs simples.","p":["Contrôler ses mouvements en mobilisant ses ressources affectives, kinesthésiques, visuelles et sa respiration.","Enrichir sa motricité d’éléments techniques : saut, tour, porter, chute….","Espace : créer des formes corporelles variées et originales en explorant ses possibilités motrices dans les trois dimensions de l’espace (haut/bas, arrière/avant, droite/gauche) en jouant sur l’inversion, le décalage, la répétition dans des orientations différentes.","Temps : faire varier les durées du mouvement : la pause, l’accéléré, le ralenti","Temps : utiliser les éléments significatifs du monde sonore et agir en relation avec les différentes parties musicales.","Energie : combiner différentes énergies en rapport avec un thème choisi, jouer sur les contrastes (tendu/relâché, solide/fondant…)."],"r":["Le chorégraphe : suggérer et sélectionner les propositions en relation avec le choix du thème et l’effet à produire sur le spectateur en jouant sur les formes corporelles, les types de relation, l’organisation de l’espace, les costumes, la musique, les silences.","Le chorégraphe : organiser le scénario de la chorégraphie.","Le spectateur : repérer les procédés de composition utilisés.","Le spectateur : apprécier la qualité d’interprétation individuelle et collective des danseurs : qualité de mouvement et degré de présence.","Le spectateur : argumenter sur les effets ressentis."]},"Basket-ball":{"cp":4,"a":"Dans un jeu à effectif réduit, rechercher le gain du match en assurant des montées de balle rapides quand la situation est favorable ou en organisant une première circulation de la balle et des joueurs pour mettre un des attaquants en situation favorable de tir quand la défense est replacée. S’inscrire dans le cadre d’un projet de jeu simple lié aux tirs en situation favorable. Observer et co-arbitrer.","p":["Gérer son effort pour enchainer plusieurs matchs de 2 fois 6 à 8 minutes ou une fois 10 minutes.","Coordonner ses actions avec celles de ses partenaires.","Elaborer un projet d’organisation collective simple, à partir des observations transmises, permettant le choix d’un jeu en pénétration ou d’un jeu placé.","Le PB : se construire une zone de tir favorable.","Le PB : effectuer un tir à l’arrêt à 2,50m de la cible ou enchaîner un tir en suspension après un dribble ou une passe sous pression temporelle.","Le PB : effectuer des passes longues et précises.","Le PB : réussir à réduire le temps d’enchaînement dribble-passe pour profiter des échanges possibles vers l’avant malgré la présence d’un défenseur proche.","Le PB : utiliser le pied de pivot pour protéger son ballon et calmer le jeu pour attendre une situation de passe favorable.","Le PB : enchaîner des déplacements vers l’avant après un échange réussi (passe et va, passe et suit).","Le PB : choisir à bon escient entre un jeu de progression ou un jeu placé selon la position de la défense.","Le NPB : réceptionner une passe longue à l’arrêt ou en course.","Le NPB : s’organiser en fonction de ses partenaires pour toujours offrir un relais ou un soutien au PB.","Le NPB : traverser la raquette pour offrir des solutions de passes au PB.","Le NPB : ressortir de la défense pour écarter le jeu.","En défense : choisir entre se replacer ou gêner le PB.","En défense : enchaîner les actions défensives après le rebond et la contre-attaque : relais court, courir vers l’avant en regardant le PB."],"r":["Le co-arbitre : arbitrer à plusieurs en se répartissant les rôles.","Le co-arbitre : se déplacer en coordination avec les joueurs et son ou ses co-arbitres.","Le co-arbitre : effectuer le geste correspondant à la faute signalée en organisant la réparation.","Le co-arbitre : connaître le score à tout moment de la rencontre.","L’observateur : repérer une situation favorable et son exploitation.","L’observateur : rendre compte de l’efficacité des actions de l’équipe et des joueurs observés."]},"Football":{"cp":4,"a":"Dans un jeu à effectif réduit, rechercher le gain du match en assurant les montées de balle collectives par une continuité des actions avec et sans ballon. S’inscrire dans le cadre d’un projet de jeu simple lié aux tirs en situation favorable. Observer et coarbitrer.","p":["Identifier son placement en défense comme en attaque.","Elaborer un projet d’organisation collective simple lié à l’efficacité offensive et défensive à partir des observations transmises.","Coordonner ses actions avec celles de ses partenaires.","Gérer son effort pour enchaîner plusieurs matchs de 2 fois 8 à 12 minutes.","Le PB : choisir par rapport à sa position sur le terrain et en fonction du rapport d’opposition, de réaliser un contrôle orienté pour se déplacer rapidement vers l’avant en conduisant le ballon, se libérer d’un adversaire, enchaîner une frappe ou un duel face au gardien de but pour marquer.","Le PB : jouer en appui court ou plus long au sol, enchaîner des actions de passe et de déplacement pour donner et recevoir le ballon en mouvement.","Le NPB : enchaîner des actions de placement, de déplacement et de replacement.","Le NPB : s’écarter du PB et s’orienter pour assurer la continuité du jeu.","Le NPB : solliciter le ballon entre les défenseurs dans le sens du but attaqué (appel profond).","Le NPB : décrocher d’une position dos au but attaqué (appui au porteur de balle).","En défense : se placer et se replacer pour se répartir les rôles entre partenaires.","En défense : agir sur le PB : le presser, le harceler pour tenter de récupérer le ballon.","En défense : réaliser un recul-frein pour ralentir la progression adverse.","En défense : orienter le porteur du ballon afin de l’isoler.","En défense : dissuader les passes et jaillir pour intercepter le ballon."],"r":["Le co-arbitre : arbitrer à plusieurs en se répartissant les rôles.","Le co-arbitre : se déplacer en coordination avec les joueurs et son ou ses co-arbitres.","Le co-arbitre : effectuer le geste correspondant à la faute signalée en organisant la réparation.","Le co-arbitre : connaître le score à tout moment de la rencontre.","L’observateur : repérer une situation favorable et son exploitation.","L’observateur : rendre compte de l’efficacité des actions de l’équipe et des joueurs observés."]},"Handball":{"cp":4,"a":"Dans un jeu à effectif réduit, rechercher le gain du match en assurant des montées de balle rapides quand la situation est favorable ou en organisant une première circulation de la balle et des joueurs pour mettre un des attaquants en situation favorable de tir quand la défense est replacée. S’inscrire dans le cadre d’un projet de jeu simple lié aux tirs en situation favorable. Observer et co-arbitrer.","p":["Gérer son effort pour réaliser plusieurs matchs de 8 minutes sans perte d’efficacité. En attaque","S’engager dans un projet collectif en construisant des repères communs pour mettre un partenaire en situation favorable de tir.","Occuper collectivement l’espace en écartement et étagement.","S’informer avant d’agir sur l’espace de jeu et le niveau d’adversité, mettre ces informations en relation avec ses possibilités techniques et celles de ses partenaires.","Prendre en compte le rapport de force pour choisir entre un jeu en montée de balle rapide ou d’attaque placée autour de la zone.","Faire des choix pertinents d’actions pour atteindre la cible, en tant que PB : jouer dans le couloir de jeu direct ou indirect par passes, dribble et / ou tir.","Faire des choix pertinents d’actions pour atteindre la cible, en tant que PB : jouer en évitement/débordement : passe et va, relais, exploitation de l’appui et du soutien.","Faire des choix pertinents d’actions pour atteindre la cible, en tant que NPB : se démarquer, jouer en appui ou en soutien.","Faire des choix pertinents d’actions pour atteindre la cible, en tant que NPB : créer des espaces libres pour ses partenaires.","Maîtriser et coordonner des actions motrices : passer et recevoir en mouvement.","Maîtriser et coordonner des actions motrices : réceptionner et tirer en utilisant une gamme de tirs dans différents secteurs (de l’aile, à 9/10 m, à 6m). En défense","S’organiser collectivement en se répartissant les rôles pour : stopper ou ralentir la montée de balle et assurer le repli défensif.","S’organiser collectivement en se répartissant les rôles pour : défendre sur ½ terrain : se placer, se replacer entre l’attaquant et le but.","Mettre en œuvre des intentions défensives pour récupérer la balle : gêner, harceler, dissuader, intercepter, aider."],"r":["Le co-arbitre : arbitrer à plusieurs en se répartissant les rôles.","Le co-arbitre : se déplacer en coordination avec les joueurs et son ou ses co-arbitres.","Le co-arbitre : effectuer le geste correspondant à la faute signalée en organisant la réparation.","Le co-arbitre : connaitre le score à tout moment de la rencontre.","L’observateur : repérer une situation favorable et son exploitation.","L’observateur : rendre compte de l’efficacité des actions de l’équipe et des joueurs observés."]},"Rugby":{"cp":4,"a":"Dans un jeu à effectif réduit, rechercher le gain d’un match en enchaînant des actions offensives basées sur l’alternative de jeu en pénétration ou en évitement face à une défense qui cherche à bloquer le plus tôt possible la progression du ballon. S’inscrire dans le cadre d’un projet de jeu simple lié au franchissement de la ligne d’avantage. Observer et coarbitrer.","p":["Percevoir et décoder l’activité des partenaires et adversaires proches.","Gérer son engagement physique afin d’être efficace sur l’ensemble d’un match.","Analyser les observations transmises et bâtir un projet de jeu simple lié au franchissement de la ligne d’avantage.","En attaque : faire le choix d’un jeu déployé ou d’un jeu groupé en fonction de la position des défenseurs.","En attaque : orienter les courses vers l’en-but adverse en accélérant à la prise de balle pour franchir un intervalle ou fixer / passer.","En attaque : percuter ou cadrer déborder dans des situations de un contre un.","En attaque : libérer la balle pour ses partenaires et/ou avoir un rôle sans ballon lors des regroupements.","En attaque : régler sa course sur celle du porteur de balle pour offrir un soutien latéral proche et en mouvement.","En attaque : soutenir le PB en assurant des rôles précis dans les regroupements (arracheur, pousseur, protecteur).","En défense : reconstituer le rideau défensif au cours du jeu, notamment autour des regroupements, en respectant les lignes de hors-jeu.","En défense : rechercher à plaquer systématiquement le PB pour augmenter ses chances de récupérer le ballon.","En défense : s’organiser collectivement pour avancer vers le PB pour diminuer son temps d’initiative et réduire la progression adverse."],"r":["Le co-arbitre : arbitrer à plusieurs en se répartissant les rôles.","Le co-arbitre : se déplacer en coordination avec les joueurs et son ou ses co-arbitres.","Le co-arbitre : siffler fort pour interrompre le jeu et expliquer à voix haute ses décisions.","Le co-arbitre : effectuer le geste correspondant à la faute signalée en organisant la réparation.","Le co-arbitre : connaître le score à tout moment de la rencontre.","L’observateur : repérer une situation favorable et son exploitation.","L’observateur : rendre compte de l’efficacité des actions de l’équipe et des joueurs observés."]},"Volley-ball":{"cp":4,"a":"Dans un jeu à effectif réduit, rechercher le gain d’un match en organisant, en situation favorable, l’attaque intentionnelle de la cible adverse par des balles accélérées ou placées face à une défense qui s’organise. S’inscrire dans le cadre d’un projet de jeu simple lié à l’efficacité de l’attaque. Observer et co-arbitrer.","p":["Se placer en orientation partagée pour voir partenaires et adversaires.","Se déplacer rapidement pour jouer équilibré et se rendre immédiatement disponible pour la frappe suivante.","Doser l’énergie donnée à la balle.","Différencier : les situations favorables d’attaque permettant de marquer soit directement, soit en mettant en jeu un attaquant.","Différencier : les situations défavorables nécessitant de monter la balle dans son camp afin de donner du temps à ses partenaires pour renvoyer.","Le réceptionneur : conserver le ballon dans son camp par une passe haute et oblique vers l’avant ou conserver le ballon haut au centre du terrain en situation de crise ou encore, s’il est situé en zone avant, renvoyer directement après avoir perçu une zone vulnérable dans le terrain adverse.","Le non réceptionneur : se déterminer en tant que soutien ou futur attaquant, se déplacer et se placer en conséquence (enchaînement des actions).","Le joueur avant : s’orienter de façon partagée ; repérer les zones vulnérables ; décider selon le contexte d’attaque (favorable ou défavorable) de renvoyer pour marquer (en prenant de vitesse ou en mettant à distance) ou conserver pour faire attaquer un partenaire (balle parallèle au filet et haute pour donner du temps).","L’attaquant : repérer les zones mal défendues ; s’écarter du filet pour offrir au passeur une possibilité de différer l’attaque ; placer la balle dans une zone vulnérable ou produire une trajectoire tendue pour mettre un adversaire en crise de temps.","L’attaquant : elaborer un projet de jeu simple permettant de s’organiser à deux ou à trois pour défendre sa cible et attaquer la cible adverse."],"r":["Le co-arbitre : Repérer les fautes notamment au filet et effectuer les gestes correspondants.","Le co-arbitre : Arbitrer à plusieurs en se répartissant les rôles.","Le co-arbitre : Connaître le score à tout moment de la rencontre. L’observateur","Le co-arbitre : Repérer une situation favorable et son exploitation.","Le co-arbitre : Rendre compte de l’efficacité des actions de l’équipe et des joueurs observés."]},"Badminton":{"cp":4,"a":"Rechercher le gain d’une rencontre en construisant le point, dès la mise en jeu du volant et en jouant intentionnellement sur la continuité ou la rupture par l’utilisation de coups et trajectoires variés. Gérer collectivement un tournoi et aider un partenaire à prendre en compte son jeu pour gagner la rencontre.","p":["Varier les services produits selon deux modalités (court et rasant ou long et haut, à droite ou à gauche) en fonction du placement de l’adversaire, de son point faible.","Créer un lien entre le service et le renvoi probable pour préparer le coup suivant.","En situation favorable, reconnaître les paramètres essentiels de la trajectoire adverse (direction, la hauteur, la vitesse, la profondeur) pour mettre l’adversaire en difficulté en accélérant par une attaque smashée ou un rush et/ou en plaçant le volant par une mise à distance.","Combiner le jeu en profondeur (contre-amorti et lob) et le jeu en largeur","Accélérer le jeu par des trajectoires plus aplaties.","Produire des frappes de sauvegarde (lob haut et profond, dégagement de défense) lors d’un retard, afin de ne pas perdre le point directement et de se donner du temps.","Augmenter la précision des dégagements (plus profonds) et des amortis (plus rasants et proches du filet).","Se relâcher pour pouvoir accélérer la frappe et être tonique au moment de l’impact.","Frapper le volant au dessus de la tête ou en avant selon la trajectoire voulue (montante ou descendante).","Se déplacer rapidement pour frapper équilibré et se replacer immédiatement en fonction de la probabilité de retour.","Construire des schémas de jeu simples à partir des données recueillies par l’observateur.","Se rappeler les conseils donnés par son partenaire pour les exploiter.","Gérer son effort pour réaliser plusieurs sets ou plusieurs matchs sans perte d’efficacité."],"r":["L’arbitre/organisateur : effectuer le geste correspondant à la faute identifiée.","L’arbitre/organisateur : se répartir les rôles pour gérer un tournoi et reporter les résultats pour organiser la suite des rencontres.","L’arbitre/organisateur : proclamer le résultat final d’un tournoi.","L’observateur/conseiller : repérer un point fort et un point faible du camarade observé.","L’observateur/conseiller : a partir des constats précédents, conseiller son partenaire pour définir un projet de jeu simple."]},"Tennis de table":{"cp":4,"a":"Rechercher le gain d’une rencontre en construisant le point, dès la mise en jeu, pour rompre l’échange par des frappes variées en vitesse et en direction, et en utilisant les premiers effets sur la balle notamment au service. Gérer collectivement un tournoi et aider un partenaire à prendre en compte son jeu pour gagner la rencontre.","p":["Se créer une arme au service en jouant placé, accéléré et/ou avec effets simples.","Créer un lien entre le service et le renvoi probable pour préparer la balle suivante.","Jouer latéralement (et aussi en profondeur au service) en exploitant le point faible adverse.","En situation favorable, reconnaître les paramètres essentiels de la balle adverse (la direction, la hauteur, la vitesse, la profondeur) pour mettre l’adversaire en difficulté en accélérant et/ou en plaçant la balle.","Se placer rapidement pour frapper équilibré en différenciant le temps de déplacement du temps de frappe.","Se replacer immédiatement après avoir été débordé afin d’être de nouveau disponible pour la frappe suivante.","Se rappeler les conseils donnés par son partenaire pour les exploiter.","Construire des schémas de jeu simples à partir du service, notamment avec effet."],"r":["L’arbitre / organisateur : se répartir les rôles pour gérer un tournoi et reporter les résultats pour organiser la suite des rencontres.","L’arbitre / organisateur : repérer un point fort et un point faible du camarade observé et de son adversaire.","L’arbitre / organisateur : a partir des constats précédents, conseiller un partenaire pour définir un projet de jeu simple."]},"Boxe française":{"cp":4,"a":"Rechercher le gain d’un assaut en privilégiant l’enchaînement de techniques offensives et défensives variées. Gérer collectivement un tournoi et observer un camarade pour le conseiller.","p":["Analyser ses résultats, repérer un point fort et un pont faible de son adversaire pour élaborer en complicité avec l’observateur une stratégie d’assaut","En attaque : Apprécier les distances","En attaque : Construire des attaques précises en s’adaptant à un adversaire mobile pour toucher exclusivement avec l’extrémité des segments (pieds ou poings)","Varier les formes d’attaque : variété des lignes et cibles visées, variété des techniques et armes utilisées en contrôlant la puissance et la trajectoire des coups en situation d’opposition","Combiner des attaques avec enchaînement de pied(s) et/ou poing(s), sur les différents niveaux de cibles autorisées","Enchaîner les attaques selon les réactions de l’adversaire","Alterner des déplacements avant et arrière avec des déplacements latéraux afin d’optimiser ses attaques et ripostes","Repérer les cibles libérées","Construire et réaliser une tactique à partir de l’analyse de ses résultats, des observations transmises, du point fort et du point faible de son adversaire","En défense : Réaliser des moyens de protection adaptés aux attaques adverses (parade protection, bloquée, chassée, et/ou esquives totales, partielles) pour pouvoir riposter (un ou deux coups)"],"r":["L’arbitre : arbitrer en utilisant la gestuelle adaptée","L’arbitre : coordonner ses actions avec celles des autres officiels","Le juge : déterminer le gagnant de l’assaut en respectant la cotation des touches","Le juge : repérer les enchaînements de touches en poings et pieds","Le juge : répondre à la demande de sanction en utilisant la gestuelle correspondante","L’observateur/conseiller : identifier un point fort et un point faible chez l’adversaire pour conseiller un camarade","L’observateur/conseiller : utiliser des critères objectifs et fiables pour élaborer une tactique appropriée","L’organisateur/chronométreur : organiser le tournoi et distribuer les rôles","L’organisateur/chronométreur : déclencher et arrêter le chronomètre en fonction des commandements de l’arbitre"]},"Lutte":{"cp":4,"a":"Rechercher le gain d’un combat debout en exploitant des opportunités et en utilisant des formes d’attaques variées. Gérer collectivement un tournoi et observer un camarade pour le conseiller.","p":["Savoir chuter et faire chuter sans risque sur des projections basses réalisées avec au moins un genou au sol pour l’attaquant.","Analyser ses résultats, repérer un point fort et un point faible de son adversaire pour élaborer en complicité avec l’observateur une stratégie de combat.","En attaque : passer d’une position de garde à un contrôle sur l’adversaire.","En attaque : enchaîner les actions en réalisant des liaisons de contrôle simple debout et/ou au sol.","En attaque : identifier le sens du déséquilibre adverse à partir du contrôle et des pressions de son corps en attaque ou en défense pour choisir une forme de corps adaptée.","En attaque : exploiter des contrôles et des formes de corps variés sur l’adversaire pour l’amener au sol.","En attaque : coordonner des actions de directions opposées avec les bras et les jambes.","En attaque : enchaîner des actions d’attaques simples dans des sens et directions différentes selon les réactions adverses.","En attaque : réaliser différentes finales à bon escient.","En attaque : au sol surpasser son adversaire en exploitant son déséquilibre.","En défense : bloquer ou parer les attaques directes.","En défense : riposter par des passages arrière au sol."],"r":["L’arbitre : arbitrer en utilisant la gestuelle adaptée.","L’arbitre : détecter des attitudes passives simples des combattants.","Le juge : communiquer avec l’arbitre pour confirmer une décision ou afficher son désaccord.","Le juge : tenir une feuille de score : marquer les points dans l’ordre, noter le résultat du combat.","L’observateur/conseiller : identifier un point fort et un point faible chez l’adversaire pour conseiller un camarade.","L’observateur/conseiller : aider à l’élaboration d’une tactique appropriée en relation avec le repérage et l’exploitation des opportunités, les contrôles et formes d’attaques utilisées.","L’organisateur/chronométreur : organiser le tournoi et distribuer les rôles.","L’organisateur/chronométreur : déclencher et arrêter le chronomètre en fonction des commandements de l’arbitre."]}},"N3":{"Demi-fond":{"cp":1,"a":"","p":["Gérer avec efficacité ses ressources pour établir la meilleure performance sur une série de courses.","Construire une attitude de course équilibrée et efficiente (épaules basses, bras relâchés…).","Adapter les foulées aux allures visées.","Maîtriser des allures à différents pourcentages de sa VMA et les maintenir sur des durées précises.","Bien expirer pour garantir l'efficacité des échanges respiratoires.","Adapter le mode de récupération (passive, active) aux efforts effectués, aux effets recherchés."],"r":["S’échauffer en sollicitant le système cardio-vasculaire et particulièrement les loges musculaires du train inférieur.","Construire et réguler son projet d’allure en fonction des indicateurs sur soi, de son ressenti et des observations transmises par des partenaires.","Conseiller un partenaire à partir d’indicateurs spatiaux et temporels (nombre de plots, temps intermédiaires, performance finale..) ou identifiés sur l’attitude de course, sur la gestion de la course.","Travailler, par petits groupes, en autonomie."]},"Course de haies":{"cp":1,"a":"","p":["Assurant la continuité des actions et franchir les obstacles avec efficacité pour réaliser la meilleure performance.","Maintenir sa vitesse de course du début à la fin de la course.","Développer et gérer son potentiel physique.","Ne pas piétiner ni ralentir pour franchir l’obstacle.","Préciser sa distance d’impulsion.","Identifier et reproduire un nombre de foulées inter-obstacles optimal.","Attaquer la haie avec l’une ou l’autre jambe.","Garder le plus possible son centre de gravité à hauteur constante.","Attaquer la haie dans l’axe.","Rechercher une reprise d’appuis rapide derrière la haie.","Stabiliser une attitude de course équilibrée sur et entre les haies (placement, relâchement…)."],"r":["S’échauffer en sollicitant les groupes musculaires, particulièrement ceux du train inférieur.","Récupérer : s’étirer…","Prendre de l’information dans sa course pour caractériser son comportement au niveau du franchissement, et entre les obstacles.","Réguler son projet en fonction de son ressenti et des observations des partenaires.","Renseigner un partenaire à partir d’indicateurs visuels simples (nombre de foulées, distance de l’impulsion à la haie, centre de gravité…).","Fonctionner ou travailler par petits groupes hors de la présence immédiate de l’enseignant."]},"Relais-vitesse":{"cp":1,"a":"","p":["Assurer la meilleure coordination des vitesses au service d’une transmission efficiente pour réaliser la meilleure performance.","Le relayé : conserver sa vitesse de course jusqu’à la transmission du témoin.","Le relayé : garder son équilibre en présentant le témoin.","Le relayé : construire et affiner le moment de la transmission : préciser les marques pour la mise en action du relayeur, communiquer efficacement (« hop ») pour le placement de la main du relayeur, transmettre correctement le témoin sur main ouverte du relayeur en maintenant la vitesse du témoin la plus élevée possible.","Le relayeur : automatiser une attitude d’attente « dynamique » pour réagir efficacement dès l’arrivée du partenaire au repère bien identifié.","Le relayeur : orienter ses appuis puis son regard dans l’axe de la course.","Le relayeur : acquérir rapidement sa vitesse maximale sans regarder derrière soi.","Le relayeur : placer et fixer sa main au signal du relayé pour prendre le témoin rapidement en ayant atteint une vitesse optimale."],"r":["S’échauffer en sollicitant les groupes musculaires particulièrement ceux du train inférieur.","Mener une récupération adaptée aux efforts réalisés (étirements, footing,.).","Identifier le résultat de ses actions (ressenti, remarques des autres relayeurs et des observateurs) pour réguler.","Conseiller les coureurs à partir de critères simples (attitudes, respect des marques, situation dans le couloir, lieu de la transmission, gestion des vitesses,…).","Fonctionner ou travailler par petits groupes hors de la présence immédiate de l’enseignant."]},"Lancer de disque":{"cp":1,"a":"","p":["Lancer le plus loin possible en assurant la continuité des actions et l’accélération du disque.","Amener le bras lanceur dans le prolongement de la ligne des épaules.","Rester équilibré pendant l’élan et le lancer.","Accélérer l’action des appuis près du sol, tout en retardant le train supérieur (et assurer le « vissage »).","Déclencher le lancer à partir de la pose solide du pied avant gauche si lanceur droitier pour optimiser le « dévissage ».","Positionner correctement le disque sur sa trajectoire avec un angle d’attaque approprié."],"r":["S’échauffer en intégrant les mobilisations articulaires sécuritaires (préparer et favoriser la dissociation des ceintures).","Récupérer, s’étirer….","Identifier le résultat de ses actions (pour réguler).","Conseiller un partenaire à partir d’indicateurs visuels simples : sur le disque, sur le lanceur.","Fonctionner ou travailler par petits groupes hors de la présence immédiate de l’enseignant."]},"Lancer de javelot":{"cp":1,"a":"","p":["Enchaîner de manière continue et accélérée : placement, course d’élan, phase de double appui et lancer.","Maintenir le javelot dans l’axe du lancer.","Construire le double appui avec l’intention de laisser le javelot loin derrière (épaule et bras libre pivotant vers l’avant, bras lanceur relâché en arrière) tout en allant chercher le sol loin devant.","Déclencher le lancer à partir d’appuis ancrés au sol.","Prendre conscience d’un appui gauche solide.","Prolonger l’alignement « jambe d’appui-tronc ».","Prolonger l’action du lancer jusqu’au niveau du poignet.","Régulariser le rythme de sa course d’élan."],"r":["S’échauffer en intégrant les mobilisations articulaires sécuritaires : préparer et favoriser la dissociation des ceintures…","Récupérer : s’étirer….","Savoir prendre ses marques pour stabiliser l’élan.","Identifier le résultat de ses actions pour les réguler.","Conseiller un partenaire à partir d’indicateurs visuels simples : sur le javelot, sur le lanceur …","Fonctionner ou travailler par petits groupes hors de la présence proche de l’enseignant."]},"Saut en hauteur":{"cp":1,"a":"","p":["Sauter le plus haut possible en assurant la continuité des actions et un placement optimal à l’impulsion.","Stabiliser la course d’élan (forme, rythme et longueur).","Coordonner les actions propulsives de la jambe d’appel avec l’action des segments libres.","Prendre les informations visuelles utiles pour se situer et apprécier la trajectoire de son corps.","Identifier et adopter des postures qui préservent l’intégrité physique notamment pour les réceptions.","Gérer un concours pour ne réaliser qu’une quantité de sauts pré - établie."],"r":["S’échauffer, seul, en sollicitant, principalement, les muscles du train inférieur. en intégrant les mobilisations articulaires sécuritaires et efficientes pour favoriser la dissociation des lignes (appuis, bassin, épaules).","Récupérer : s’étirer…","Identifier le résultat de ses actions (pour réguler).","Conseiller un partenaire à partir d’indicateurs visuels simples : pied d’appel (position, respect des marques..), attitude du corps à l’impulsion (un alignement cheville-bassin-épaules,.),…","Fonctionner ou travailler par petits groupes hors de la présence immédiate de l’enseignant."]},"Pentabond":{"cp":1,"a":"","p":["Sauter le plus loin possible en assurant la continuité des actions et en maintenant un placement optimal à chaque impulsion.","Construire un élan progressivement accéléré pour atteindre une vitesse optimale.","Choisir une distance d’élan en rapport avec ses qualités motrices.","Savoir prendre ses marques.","Adopter une attitude de course qui permettre un appel efficace,","Produire des trajectoires adaptées à la continuité des bonds recherchée (équilibre, pas « d’écrasement »…)","Mobiliser la jambe libre (genou haut vers l’avant) et les bras lors de l’équilibration du saut lors des foulées bondissantes","Mobiliser ses segments en vue de préserver l’intégrité physique, spécifiquement lors des réceptions","Gérer ses ressources pour optimiser l’ensemble de ses performances lors d’un concours."],"r":["S’échauffer, seul, en sollicitant, principalement, les muscles du train inférieur, en intégrant les mobilisations articulaires sécuritaires et efficientes pour favoriser la dissociation des lignes (appuis, bassin, épaules).","Récupérer : s’étirer…","Repérer les différentes phases du pentabond.","Identifier le résultat de ses actions (pour réguler).","Conseiller un partenaire à partir d’indicateurs visuels simples : pied d’appel (position, respect des marques/planche..), attitude du corps pendant sur le pentabond et lors de la dernière impulsion (alignement cheville-bassin-épaules,.),…","Fonctionner ou travailler par petits groupes hors de la présence immédiate de l’enseignant."]},"Natation de vitesse":{"cp":1,"a":"","p":["Nager vite en recherchant la continuité des actions propulsives.","S’inscrire sur un équilibre horizontal pour réduire les résistances frontales à l’avancement: (fixer la position de la tête dans le prolongement du corps).","Construire une expiration aquatique spécifique à la vitesse.","Accentuer l’efficacité des battements en diminuant leurs possibles actions frénatrices (battements désaxés, désordonnés).","Adopter une fréquence de nage en cohérence avec une épreuve de vitesse (par ex : entre 27 et 30 cycles de bras /mn).","Construire des techniques de virage permettant un gain de distance, en s’intéressant essentiellement aux phases de poussée-coulée.","Ajuster la phase de reprise de nage en identifiant le moment le plus opportun.","Réaliser une reprise de nage : coulée, battements, bras, puis respiration.","Rechercher des trajets propulsifs offrant des appuis larges, perpendiculaires à l’axe de déplacement.","Construire la position hydrodynamique à l’aide de différents départs et poussées contre le mur pour gagner du temps."],"r":["S’échauffer.","Utiliser le chronomètre mural pour mesurer ses performances et gérer les temps de repos.","Renseigner un camarade sur sa prestation à partir d’indices qualitatifs et quantitatifs (nombre de coups de bras en rapport avec la vitesse,….position de la tête).","Analyser sa course et/ou celle de camarades à partir d’indices qualitatifs et quantitatifs."]},"Natation de distance":{"cp":1,"a":"","p":["Nager régulièrement pour pouvoir accélérer en fin de parcours.","Savoir réguler sa vitesse de nage.","S’inscrire dans un équilibre horizontal pour se déplacer longtemps : position de la tête dans le prolongement du corps (prise de repères au fond ou au plafond).","Trouver l’action équilibratrice des battements en mobilisant la hanche et en accentuant le relâchement de la cheville.","Adopter une inspiration brève suivie d’une expiration aquatique longue et complète.","Produire des trajets propulsifs amples, axés, tête stabilisée.","Développer l’amplitude dans le souci de durer.","Construire des techniques de virage permettant d’optimiser les phases de poussée-coulée."],"r":["S’échauffer.","Utiliser le chronomètre mural pour réaliser précisément son entraînement.","Analyser sa course et/ou celle de camarades à partir d’indices qualitatifs et quantitatifs.","Renseigner un camarade sur sa prestation à partir d’indices qualitatifs et quantitatifs (nombre de coups de bras en rapport avec la vitesse, position de la tête, moment de l’inspiration, régularité des parcours …)."]},"Escalade":{"cp":2,"a":"","p":["Identifier le niveau de voie accessible en fonction de ses ressources et repérer les passages difficiles.","Pendant l’action : conduire, réguler, adapter son déplacement.","S’engager et soutenir l’effort sur l’ensemble de la séance.","Répartir son effort et la vitesse de sa progression en fonction des caractéristiques de la voie pour la réussir.","Orienter son regard vers l’anticipation de la progression.","Acquérir une routine d’échauffement global et spécifique.","S’équiper, s’encorder sans hésitations.","Se confronter à l’utilisation d’une variété de prises (verticales, réglettes, crochetantes, inversées…) et se placer à bon escient.","Privilégier l’action des jambes, un placement différencié et contrôlé, prendre appui au niveau de la pose de pieds principalement sur l’avant.","Placer le bassin au dessus de l’appui pour le charger.","Se rééquilibrer et se protéger par les pieds et les mains lors d’une chute.","Adopter une posture efficace et relâchée lors de la descente et faire descendre le grimpeur à vitesse régulière et contrôlée.","Assurer en moulinette (A, B, C, D), se placer à distance optimale de la voie.","Pour l’assureur, anticiper et éprouver la chute du grimpeur.","Pour le pareur en bloc, se placer à bonne distance d’intervention dans une attitude pré-active mains décalées (hanche, épaule).","Se placer en contre-assureur si nécessaire."],"r":["En coopération : vérifier l’équipement de son équipier (nœud ou matériel d’assurage) et le corriger.","En coopération : émettre des hypothèses alternatives en cas échec.","Pour un progrès personnel : reconnaître les indices qui annoncent une chute.","Pour un progrès personnel : par observation d’un grimpeur, repérer les passages difficiles et mémoriser les trajets efficaces observés chez un grimpeur."]},"Course d’orientation":{"cp":2,"a":"","p":["Avant le déplacement : concevoir, prévoir, anticiper son itinéraire.","Prévoir les lignes d’arrêt et point d’attaque de poste.","Construire son itinéraire en suivant des lignes directrices de différents niveaux.","Utiliser une boussole : pour orienter sa carte en l’absence d’éléments remarquables, ou pour « attaquer » un poste.","Pendant l’action : conduire, réguler, adapter son déplacement.","S’engager et gérer son effort pour mener à terme son projet d’itinéraire.","Réguler sa course en fonction de sensations ressenties et des observations éventuelles des équipiers.","Adopter une allure de course permettant de garder une vigilance et une lucidité suffisante pour se repérer.","Évaluer approximativement une distance sur le terrain.","Affiner sa motricité spécifique.","Adapter sa foulée, son allure et son attitude de course aux caractéristiques du terrain.","Agir en sécurité.","Organiser son retour dans le temps imparti.","Remplir convenablement un carton de contrôle (définir un poste, poinçonner)."],"r":["Comparer ses choix d’itinéraires avec les autres.","Partager ses connaissances avec ses partenaires.","Émettre des hypothèses alternatives en cas échec.","Tenir un tableau de gestion de course (heure de départ, d’arrivée, temps course, etc.)","Se remémorer l’itinéraire parcouru.","Retranscrire oralement ou sur la carte son itinéraire."]},"Natation de sauvetage":{"cp":2,"a":"","p":["Avant le déplacement : concevoir, prévoir, anticiper son itinéraire.","Prévoir nombre d’obstacles et la distance à parcourir.","Pendant l’action : conduire, réguler, adapter son déplacement.","Se déplacer de façon variée (déplacement de surface, surplace, en immersion avec ou sans franchissements d’obstacles) et réguler sa vitesse à l’approche de l’obstacle.","Gérer son allure en fonction de la distance totale restant à parcourir, les obstacles à franchir et du temps disponible.","Affiner sa motricité spécifique.","Réaliser un plongeon canard : passer d’un déplacement horizontal à un déplacement vertical en mobilisant les bras et la tête.","Réaliser des remontées d’objets.","Réaliser un surplace avec l’objet.","Utiliser une nage hybride.","Moduler la longueur du trajet des appuis, et ajuster la quantité et l’orientation des surfaces propulsives (mouvements courts en situation de sauvetage) en fonction de l’usage de la nage.","Adopter et adapter une technique de nage permettant : D’anticiper la distance nécessaire pour franchir l’obstacle. Repérer l’obstacle avec ou sans rupture de nage en fonction de l’état de fatigue avant le plongeon canard, Franchir les obstacles à moindre coût énergétique et sans le toucher (bras simultanés puis jambes simultanées).","Adopter et adapter une technique de nage permettant : dans les zones inter-obstacles : Diminuer la fréquence des mouvements au profit de l’amplitude dans le souci de « durer ». Optimiser les parties non nagées (franchissement & virage) notamment en construisant le placement de la tête (alignement tête tronc)."],"r":["En coopération.","Mise en relation l’état de fatigue perçu et le temps imparti (gestion de la fatigue).","S’organiser à plusieurs dans le dispositif mis en place.","Juger de la conformité des franchissements.","Prévoir nombre d’obstacles et la distance à parcourir.","Décrire les sensations d’appuis et d’effort ressentis dans son parcours."]},"Acrosport":{"cp":3,"a":"","p":["Réalisation : créer et réaliser des duos, trios, quatuors en tant que porteur et voltigeur.","Réalisation : construire l’équilibre et le maintien d’une posture solide et tonique : gainage, bras et jambes tendus, alignement segmentaire, appuis sur épaules, bassin.., augmenter les surfaces d’appui, efficacité des prises, charges soulevées avec les cuisses, dos plat, compensation des masses…","Réalisation : coordonner les actions motrices (porteur/voltigeur, déplacements, liaisons) pour assurer la dynamique de l’enchaînement.","Réalisation : planifier et assurer des montages et démontages sécurisés et contrôlés (monter et démonter dans l’axe, sans précipitation et sans multiplication des appuis).","Réalisation : anticiper la répartition des différents rôles (placement du porteur, appuis du voltigeur, saisie de l’aide).","Réalisation : se repérer par rapport à l’espace d’évolution et ses partenaires.","Réalisation : soutenir son effort dans les répétitions (figures, liaisons, enchaînement).","Composition : faire des choix en fonction des exigences de la composition pour permettre une réalisation sans rupture.","Composition : créer, varier, diversifier et maîtriser des modes de liaison différents entre les figures (statiques et dynamiques) et les éléments (gymniques ou chorégraphiques).","Appréciation-jugement : repérer et identifier des figures issues du code et la conformité des exigences.","Appréciation-jugement : utiliser des indicateurs simples pour apprécier un enchaînement."],"r":["Réalisation : se préparer à l’activité par des routines construites (s’échauffer de façon générale et spécifique).","Réalisation : se placer à proximité du voltigeur et du porteur et le saisir précisément pour intervenir efficacement et rapidement.","Réalisation : se concentrer avant et pendant le passage.","Composition : faire des choix en fonction des ressources du groupe.","Appréciation-jugement : observer et juger la stabilité et la sécurité des figures d’un autre groupe à partir d’indicateurs simples."]},"Aérobic":{"cp":3,"a":"","p":["Réalisation : réaliser à droite et à gauche une dizaine de pas de base et des difficultés de niveau A : mémoriser (anticipation), exécuter (postures, énergie, amplitude).","Réalisation : coordonner/dissocier les mouvements de bras et de jambes de manière simple (simultanés ou alternatifs).","Réalisation : repérer et compter individuellement les temps en suivant le tempo de la musique.","Réalisation : réaliser les pas en synchronisation : avec la musique (repères découpage musicaux, tempo), et avec les membres du groupe.","Réalisation : se repérer dans l’espace lors des changements de blocs ou de formations.","Réalisation : soutenir son effort dans les répétitions (pas, figure, enchaînement).","Réalisation : présenter son enchaînement à un public : concentration, « show », présence.","Composition : faire des choix en fonction des exigences de la composition.","Composition : orienter l’enchaînement par rapport au public et exploiter l’espace scénique.","Appréciation-jugement : observer et apprécier une prestation à partir de critères simples (synchronisation, mémorisation, concentration).","Appréciation-jugement : repérer les formations."],"r":["Composition : les rôles dans la composition et la réalisation de l’enchaînement.","Composition : les temps d’échanges, de composition et ceux de la mise en pratique des idées, de répétition.","Appréciation-jugement : conseiller à partir de l’observation réalisée."]},"Arts du cirque":{"cp":3,"a":"","p":["Le technicien : tenir, contrôler, arrêter une circulation d’objets de jonglage précise et choisie.","Le technicien : s’équilibrer et se déplacer sans risque sur des engins à stabilité précaire.","Le technicien : créer et réaliser collectivement des figures acrobatiques en jouant sur les paramètres de temps (unisson, cascade, répétition) ou d’espace (côte à côte, lignes, colonnes…).","Le technicien : réaliser des figures issues du répertoire circassien.","Le technicien : enchaîner différentes figures sans chute.","Le technicien : soutenir son effort dans les répétitions (figures, numéro).","L'interprète : rechercher une qualité des mouvements : appuis, respiration, amplitude, volumes, précision.","L'interprète : transformer les formes pour leur donner du sens.","L'interprète : marquer les temps forts par des arrêts, des ralentis, des accélérations, des regards.","Le metteur en scène : s’engager dans une démarche de création : les figures, les techniques apprises sont un vocabulaire au service d’une intention.","Le metteur en scène : concevoir, agencer, organiser l’espace scénique grâce à la coordination de moyens techniques et artistiques (décors, accessoires, costumes, coulisses).","Le metteur en scène : exploiter les règles et principes de composition simples : unisson, cascade, répétition…","Le spectateur/ lecteur : repérer les différentes disciplines et éléments présentés."],"r":["Le technicien : prendre en compte la relation risque/sécurité.","Le technicien : préparer, ranger vérifier son matériel.","Le technicien : organiser son travail en respectant celui des autres : partager l’espace, le matériel, la musique.","Le metteur en scène : ordonner, numéroter les différentes séquences ou éléments à intégrer.","Le metteur en scène : préciser et varier les formes de groupements (nombre, relations, contacts, orientations).","Le metteur en scène : se répartir les rôles.","Le metteur en scène : schématiser les trajets, la disposition des objets et l’emplacement des accessoires.","Le metteur en scène : déterminer les formes, les natures, les durées des déplacements.","Le spectateur/ lecteur : analyser qualitativement les prestations : degré d’engagement, prises de risques maîtrisées ou non, précision dans la réalisation des figures, organisation collective…."]},"Danse":{"cp":3,"a":"","p":["Le danseur : créer et transformer le mouvement en jouant sur les différents paramètres: du point de vue de l'espace : Réaliser des mouvements dont l’origine, le trajet et la fin sont précis. Exploiter l’espace de façon variée : directions, niveaux, plans, formes, volumes. S’orienter dans l’espace par rapport à ses partenaires et aux spectateurs en lien avec ce que l’on veut donner à voir.","Le danseur : créer et transformer le mouvement en jouant sur les différents paramètres: du point de vue du temps : Varier les durées d’un mouvement : lent/vite, accéléré/décéléré…, réaliser un arrêt sur image, tenir l'immobilité. Repérer le tempo d’une musique rythmique et le traduire par le mouvement pour se placer en accord ou en rupture.","Le danseur : créer et transformer le mouvement en jouant sur les différents paramètres: du point de vue de l'énergie : Jouer sur les contrastes : saccadé/fluide, fort/faible, contenu/explosif, dur/mou, lourd/léger, rigide/élastique… Soutenir son effort lors des répétitions (geste, séquence, chorégraphie).","L'interprète : placer son regard de manière intentionnelle.","L'interprète : construire son mouvement avec un ancrage dans le sol contrôlé par des appuis corporels et une respiration en relation avec le mouvement.","Le chorégraphe : exploiter, lier les transformations de mouvements dans l'espace, le temps et l'énergie au service du projet chorégraphique.","Le chorégraphe : le spectateur/lecteur","Le chorégraphe : observer seul ou à plusieurs selon des critères simples et objectifs.","Le chorégraphe : identifier le type d’impact sur le spectateur."],"r":["Le danseur/le chorégraphe : suivre une démarche de création artistique guidée par l’enseignant","Explorer, à partir d’inducteurs (objets, documents, mondes sonores, thèmes..).","Transformer les réponses en jouant sur les paramètres du mouvement.","Choisir parmi les propositions les plus pertinentes par rapport à son projet chorégraphique.","Organiser les propositions selon les principes de composition retenus.","Mémoriser par répétitions la chorégraphie.","Présenter la chorégraphie à des spectateurs/lecteurs","Prendre en compte les observations des spectateurs/lecteurs pour de futures transformations.","Le spectateur/lecteur : lire une chorégraphie","Le spectateur/lecteur : rendre compte de ses observations et de ses impressions à un groupe pour améliorer leur prestation et faciliter les prises de décisions : l’aider à faire des choix. ."]},"Gymnastique":{"cp":3,"a":"","p":["Réalisation : maîtriser les modalités de préservation de la colonne vertébrale (enrouler, amortir, verrouiller, gainer).","Réalisation : réaliser/ maîtriser les éléments gymniques et acrobatiques de son niveau (3 familles gymniques distinctes spécifiques à l'agrès) pour pouvoir les enchaîner sans rupture.","Réalisation : réinvestir les acquis moteurs dans la réalisation d'éléments nouveaux proches (créer des élans, amorti/impulsion, complexification ..).","Réalisation : soutenir son effort dans les répétitions (éléments et séquences).","Réalisation : gérer son effort par l’identification des temps forts et faibles de son enchaînement.","Composition : organiser la composition des séquences pour permettre leur réalisation sans rupture (ordre, rythme, équilibre dynamique).","Composition : transformer le début et la fin des actions de chaque élément pour optimiser les conditions de leur enchaînement.","Composition : gérer position, posture et direction du regard pour présenter l’enchaînement avec un souci de correction.","Appréciation – Jugement : reconnaître la conformité des éléments par rapport à leur présentation (description écrite, schéma, vidéo).","Appréciation – Jugement : repérer les moments de rupture dans l’enchaînement.","Appréciation – Jugement : apprécier une prestation observée (appréciation objective) en utilisant les indicateurs de réalisation et de réussite."],"r":["Réalisation : se préparer à l'activité par des routines construites (s'échauffer de façon générale et spécifique, éléments gymniques simples).","Réalisation : régler le matériel à sa morphologie et/ou à son niveau de pratique.","Réalisation : se placer pour parer sans gêner lors de la réalisation des éléments.","Composition : choisir les éléments gymniques en rapport à son niveau de maîtrise","Appréciation – jugement : s'organiser pour juger efficacement les prestations (orientation de l'espace de prestation et de jugement).","Appréciation – jugement : repérer dans sa prestation et celle des autres le non respect des indicateurs de réalisation et de réussite."]},"Gymnastique rythmique":{"cp":3,"a":"","p":["Réalisation : coordonner, réaliser, maîtriser les éléments corporels et à l’engin pour les enchaîner sans rupture, avec ses partenaires. dans des déplacements diversifiés (forme et/ ou espace).","Réalisation : choisir et réaliser des relations simples qui s’intègrent dans les formations sans les perturber (respect des alignements et intervalles) (avec ou sans échange, avec ou sans difficulté corporelle, avec ou sans contact tout en faisant varier le nombre de gymnastes).","Réalisation : soutenir son effort dans les répétitions (manipulations, figures, enchaînement).","Composition : préciser un début et une fin en relation avec l’organisation des formations, des évolutions pour optimiser les conditions de leur enchaînement et l'effet sur le public.","Composition : organiser des évolutions qui permettent de placer des formations variées à des endroits différents de l’aire d’évolution.","Composition : organiser sa prestation selon un procédé de composition choisi.","Composition : choisir les éléments corps/engin en fonction des ressources individuelles et collectives du groupe.","Appréciation-jugement : utiliser les indicateurs de réalisation et de réussite pour apprécier la prestation observée (appréciation objective).","Appréciation-jugement : repérer dans la prestation observée la présence des éléments corporels et à l’engin définis dans le code de référence.","Appréciation-jugement : repérer les formations et évolutions utilisées et la qualité/précision de leur réalisation."],"r":["Réalisation : se préparer à l'activité par des routines construites (s'échauffer de façon générale et spécifique, présenter sa prestation).","Composition : choisir les éléments corps/engin, les formations/évolutions, les relations, pour une réalisation harmonieuse du groupe.","Appréciation-jugement : s'organiser pour juger efficacement les prestations (orientation de l'espace de prestation et de jugement).","Appréciation-jugement : repérer dans sa prestation et celle des autres le non respect des indicateurs de réalisation et de réussite."]},"Basket-ball":{"cp":4,"a":"","p":["Réaliser une préparation à l'effort collectif générale et spécifique.","Au plan collectif : progresser collectivement vers la cible adverse dès la récupération du ballon en un minimum de temps et/ou de passes.","Au plan collectif : progresser par du jeu direct ou l’utilisation d’un relais.","Au plan collectif : rechercher et exploiter la profondeur.","Au plan collectif : utiliser les couloirs latéraux.","Au plan collectif : récupérer la balle ou gêner sa progression en différenciant les rôles défensifs (défenseur sur PB et NPB ou trajectoires).","Au plan individuel : tenir et soutenir un effort optimal sur une période de jeu.","Au plan individuel : porteur de balle : Prélever les indices pertinents pour gérer l’alternative passe/progression en dribbles Rechercher prioritairement la passe dans la course d’un partenaire démarqué dans l’espace avant. Maîtriser le dribble de progression pour exploiter un espace libre vers l’avant Enchaîner, réception/tir en course et dribble/tir en course pour finir la contre-attaque.","Au plan individuel : aide au porteur de balle : Se rendre disponible dans l’espace avant et dans les couloirs latéraux dans un espace libre à distance de passe. Se déplacer de manière à voir simultanément le trajet du ballon et la cible adverse (orientation partagée PB/cible). Rompre l’alignement ballon /adversaire proche: créer des lignes de passe Aller au rebond offensif.","Au plan individuel : défenseur : Se responsabiliser par rapport à un adversaire (différencier son intervention sur PB et sur NPB). Courir pour se placer dès la perte de balle entre l’adversaire et la cible à défendre. Stopper, ralentir ou gêner la progression du PB. Intercepter les passes."],"r":["Se concerter pour améliorer l’organisation de la contre-attaque et/ou du repli défensif.","Gérer les changements de joueurs au cours d’un match","Identifier et siffler une faute (infraction à la règle du non-contact), une violation (reprise de dribble, marcher…).","Observer une séquence de jeu à l’aide de critères objectifs liés à l’efficacité de la contre- attaque.","Assurer le rôle de partenaire d'entraînement."]},"Football":{"cp":4,"a":"","p":["Réaliser une préparation à l'effort collectif générale et spécifique.","Au plan collectif : progresser collectivement vers la cible adverse dès la récupération du ballon en un minimum de temps et/ou de passes.","Au plan collectif : progresser par du jeu direct ou l’utilisation d’un relais.","Au plan collectif : rechercher et exploiter la profondeur.","Au plan collectif : utiliser les couloirs latéraux.","Au plan collectif : récupérer la balle ou gêner sa progression en différenciant les rôles défensifs (sur PB, NPB ou trajectoires).","Au plan individuel : tenir et soutenir un effort optimal sur une période de jeu.","Au plan individuel : porteur de balle : Prélever les indices pertinents pour gérer l’alternative passe/conduite de B. Rechercher prioritairement la passe dans la course d’un partenaire démarqué dans l’espace avant. Conduire sa balle sur différents rythmes. Tirer en situation de frappe favorable.","Au plan individuel : aide au porteur de balle : Se rendre disponible dans l’espace avant proche, dans un espace libre à distance de passe. Se déplacer de manière à voir simultanément le trajet du ballon et la cible adverse (orientation partagée PB/cible). Se placer en rupture d’alignement ballon /adversaire proche : créer des lignes de passe.","Au plan individuel : défenseur : Se responsabiliser par rapport à un adversaire dans sa zone (différencier PB et NPB). Se placer entre l’adversaire et la cible à défendre. Stopper, ralentir ou gêner la progression du PB. Intercepter les passes."],"r":["Élaborer un projet de jeu en utilisant l’attaque rapide.","Se concerter pour améliorer l’organisation de l’attaque rapide et/ou du repli défensif.","Gérer les changements de joueurs au cours d’un match","Identifier et siffler une faute de jeu simple, (ex charge irrégulière, hors-jeu).","Observer une séquence de jeu à l’aide de critères objectifs simples liés à l’efficacité de la contre-attaque.","Arbitrer une rencontre à plusieurs avec partage des règles à siffler","Assurer le rôle de partenaire d'entraînement."]},"Handball":{"cp":4,"a":"","p":["Réaliser une préparation à l'effort collectif générale et spécifique.","Au plan collectif : progresser collectivement vers la cible adverse selon une organisation anticipée dès la récupération du ballon en un minimum de temps et/ou de passes.","Au plan collectif : progresser par du jeu direct ou l’utilisation d’un relais.","Au plan collectif : rechercher et exploiter la profondeur.","Au plan collectif : utiliser les couloirs latéraux.","Au plan collectif : récupérer la balle ou gêner sa progression en différenciant les rôles défensifs (défenseur sur PB et NPB ou trajectoires).","Au plan individuel : tenir et soutenir un effort optimal sur une période de jeu.","Au plan individuel : porteur de balle : Prélever les indices pertinents pour gérer l’alternative passe/progression en dribbles. Rechercher prioritairement une passe longue dans la course d'un partenaire démarqué dans l’espace avant. Effectuer une passe courte à un partenaire démarqué qui se tient prêt à réceptionner la balle. Enchaîner une course avant avec la balle et un tir en suspension Tirer avec l'intention de viser les espaces inoccupés par le gardien ou les zones favorables (tirs vers le bas)","Au plan individuel : aide au porteur de balle : Se rendre disponible (espace avant, couloirs latéraux) dans un espace libre à distance de passe (notamment pour la passe venant du gardien). Se démarquer en investissant l'espace libre proche du porteur de balle, avec une attitude préparatoire à la réception du ballon (dissociation train supérieur et inférieur). Rompre l’alignement ballon /adversaire proche: créer des lignes de passes.","Au plan individuel : défenseur : Se déplacer en course arrière pour défendre l'espace proche de sa cible. Toucher le porteur de balle, en contrôlant son déplacement, afin de le gêner dans la transmission du ballon (différencier la faute défensive admise d'un acte d'anti-jeu interdit)"],"r":["Se concerter pour améliorer l’organisation de la contre-attaque et/ou du repli défensif.","Gérer les changements de joueurs au cours d’un match.","Identifier et siffler une faute.","Observer une séquence de jeu à l’aide de critères objectifs liés à l’efficacité de la contre- attaque.","Assurer le rôle de partenaire d'entraînement."]},"Rugby":{"cp":4,"a":"","p":["Réaliser une préparation à l'effort collectif générale et spécifique.","Au plan collectif : créer à plusieurs un déséquilibre dans un lieu précis du système défensif (jeu groupé) et exploiter ce déséquilibre.","Au plan collectif : communiquer (forme de jeu, replacement) avant et pendant l’action pour se rassurer et optimiser la cohérence collective.","Au plan individuel : tenir et soutenir un effort optimal sur une période de jeu.","Au plan individuel : porteur de balle : Décider de façon pertinente pour exploiter le déséquilibre (jouer seul ou transmettre, fixer et donner, prendre l'espace libre, soutenir ou se replacer). Protéger son ballon (en particulier à l'impact) pour assurer la conservation.","Au plan individuel : aide au porteur de balle : Se répartir l’espace pour conserver la balle au point de blocage (répartition des rôles): Sur joueur bloqué debout : arracher la balle puis se lier à lui afin d’isoler la balle. Sur joueur au sol : enjamber de bas en haut. Éjecter pour accélérer le jeu dans une autre zone. Se placer dans la latéralité pour jouer en déployé. Être toujours en soutien du porteur. Tenir compte des autres et modifier ses placements et replacements en fonction de ses partenaires.","Aide au porteur de balle : Se répartir l’espace pour conserver la balle au point de blocage (répartition des rôles): défenseur : S'organiser pour défendre (bloquer très tôt la progression du ballon, distinguer les attaques ballon porté, ballon au sol, ballon au large). Bloquer le porteur ou le plaquer. Adopter une posture préparatoire au placage (se baisser, attraper à bras le corps) efficace et non dangereuse. Récupérer le ballon en l’arrachant vers le bas. Récupérer le ballon en repoussant l’adversaire dans le ruck. Décentrer son regard du ballon (vers ses adversaires et partenaires)."],"r":["Identifier, sélectionner les informations pour prendre des décisions individuellement et collectivement.","Co-arbitrer en associant une gestuelle à la décision.","Repérer à l’observation une décision pertinente, dangereuse, prometteuse.","Assurer le rôle de partenaire d'entraînement."]},"Volley-ball":{"cp":4,"a":"","p":["Réaliser une préparation à l'effort collectif générale et spécifique.","Au plan collectif : s’organiser pour attaquer le fond de la cible adverse.","Au plan collectif : se répartir sur le terrain pour défendre toute la cible.","Au plan individuel : tenir et soutenir un effort optimal sur une période de jeu.","Au plan individuel : porteur de balle : Assurer régulièrement une mise en jeu réussie. S'identifier comme intervenant (réceptionneur, relayeur ou attaquant) ou non intervenant direct (soutien, aide…) et communiquer avec mes partenaires. Adopter une posture dynamique et active permettant une intervention rapide et efficace sur la balle : orientation des appuis, flexion des jambes, équilibration.","Choisir une frappe adaptée pour permettre : soit la conservation du ballon quand je suis en zone arrière ou en difficulté (haute dans mon propre camp). Soit l'attaque du terrain adverse (trajectoire tendue et si possible puissante) quand je suis en zone avant.","Choisir une frappe adaptée pour permettre : aide au porteur de balle : Adopter une attitude active pour aider mes partenaires (regard sur le ballon, orientation vers le porteur..) Se rendre disponible pour faire progresser la balle vers l’avant.","Choisir une frappe adaptée pour permettre : aide au porteur de balle : défenseur : Se positionner au fond de sa zone de défense. Se placer pour remonter le ballon devant soi."],"r":["Se concerter pour améliorer l'organisation collective de la défense de son camp et l'atteinte du fond du terrain adverse.","Apprécier globalement les raisons de la réussite ou de l’échec (individuels et collectifs) et chercher à y remédier pour progresser.","Assurer des envois de balle précis et réguliers","Assurer le bon déroulement d'un match (annoncer les fautes, le score).","Gérer les changements de joueur en cours de match","Assurer le rôle de partenaire d'entraînement."]},"Judo":{"cp":4,"a":"","p":["Réaliser une préparation à l’effort générale et spécifique.","Préalable indispensable avant le combat debout : chuter en rentrant la tête et taper avec la main libre au moment où le dos arrive au sol.","Préalable indispensable avant le combat debout : contrôler la chute d’Uke par la manche avec sa main","Combat debout : saisir l’adversaire pour prendre des informations sur ce qu’il fait, pour l’attaquer ou pour se défendre.","Combat debout : se déplacer en créant le déséquilibre de l’adversaire, le faire réagir en poussant, tirant, tournant…","Combat debout : se placer en lançant une attaque directe, en assurant un contact du haut du corps, des appuis stables et un centre de gravité sous celui de l’adversaire.","Combat debout : projeter en recherchant la rotation du partenaire autour de l’axe des hanches ou des pieds et jambes.","Combat debout : défendre en favorisant l’esquive bras souples.","Combat au sol : saisir et contrôler pour empêcher l’adversaire de se relever ou de sortir du tapis.","Combat au sol : maintenir une immobilisation 25’’ en contrôlant le haut du corps et en adaptant ses déplacements à ceux d’Uke.","Combat au sol : adopter des positions de « fermeture » (coudes collés au corps) pour ne pas se faire retourner.","Combat au sol : neutraliser un contrôle en saisissant la jambe de Tori.","Combat au sol : sortir d’immobilisation en faisant réagir Tori pour créer un intervalle et tourner à plat ventre.","Tenir et soutenir un effort sur la durée d’un combat."],"r":["Assurer le rôle de partenaire d’entraînement.","Construire des repères kinesthésiques pour maitriser le rapport risque-sécurité lors des projections et/ou des chutes.","Réaliser les actions d’attaque et de défense à différentes vitesses (débuter vitesse modérée pour mieux « sentir ») et degrés d’opposition.","Rencontrer différents partenaires, identifier les principes mis en œuvre, résoudre différents problèmes.","Assurer le rôle d’arbitre."]},"Boxe française":{"cp":4,"a":"","p":["Réaliser une préparation à l’effort générale et spécifique.","Appliquer une consigne spécifiant le rôle à tenir, les cibles et les armes autorisées pendant un temps défini d’opposition.","Déclencher des touches à distance (avec un placement et une arme appropriés) sur un adversaire mobile.","Contrôler la puissance et la trajectoire des coups en situation d’opposition à rôle déterminé.","Enchaîner deux touches (poing-poing, pied-pied ou pied-poing).","Se protéger par des parades bloquées ou des esquives permettant de rester équilibré et à distance pour éventuellement riposter.","Tenir et soutenir un effort sur la durée d’un combat."],"r":["Assurer le rôle d’arbitre.","Assurer le rôle de partenaire d’entraînement.","Analyser ses actions et leurs conséquences sur l’issue de la rencontre.","Expliciter ses choix (ses décisions) en fonction des informations prélevées (sur l’adverse, sur soi).","Décompter le score de son adversaire en annonçant les touches effectivement reçues au cours d’une reprise.","Repérer et sanctionner en cours d’opposition : une touche non contrôlée, une trajectoire verticale montante ou descendante, une arme autre que les extrémités segmentaires codifiées…","Utiliser les commandements essentiels pour le déroulement d’une confrontation : « Saluez-vous », « En garde », « Allez », « Stop ».","En situation de juge : savoir retranscrire les décisions arbitrales."]},"Badminton":{"cp":4,"a":"","p":["Réaliser une préparation à l’effort général et spécifique.","Tenir et soutenir un effort sur la durée d’une période de jeu.","En attaque : utiliser le service cuillère de façon réglementaire sans s’exposer à un retour décisif de l’adversaire.","En attaque : stabiliser deux alternatives au service : service long et profond ou court et tendu.","En attaque : varier les trajectoires : longueur, direction, forme, et vitesse…","En attaque : varier intentionnellement le placement du volant en situation de confort pour élargir la cible, sortir l’adversaire du centre.","En attaque : trouver des solutions pour créer des espaces libres dans le terrain adverse (exploiter le revers de fond de court adverse, allonger les trajectoires, varier les frappes).","En attaque : identifier les espaces libres et produire une attaque ciblée avec une trajectoire adaptée.","En attaque : identifier et saisir une situation de marque (rapport de force favorable) et produire une attaque décisive.","En attaque : adapter sa frappe à l’état du rapport de force (situation d’attaque ou de défense en fonction du point de frappe).","En attaque : tenir physiquement l’échange.","En défense : dans l’échange, se replacer systématiquement au centre du jeu.","En défense : effectuer des déplacements spécifiques (fentes et pas chassés) efficaces."],"r":["Assurer le bon déroulement d’un match (mise en œuvre du règlement : décompte des points, annonce des « fautes », des « lets »).","Identifier et verbaliser les points forts et les points faibles de l’adversaire.","Prélever des indices tactiques simples pour identifier des situations favorables de marque (déséquilibre ou retard important de l’adversaire au moment de sa frappe)","Prélever les indicateurs identifiant l’échec ou de la réussite dans le match.","Utiliser la gestuelle de l’arbitre.","Assumer le rôle de partenaire d’entraînement."]},"Tennis de table":{"cp":4,"a":"","p":["Réaliser une préparation à l’effort général et spécifique.","Tenir et soutenir un effort sur la durée d’une période de jeu.","En attaque : servir (réglementairement) sans s’exposer à un retour décisif de l’adversaire.","En attaque : prendre l’initiative dans l’échange.","En attaque : varier intentionnellement le placement de la balle.","En attaque : se placer efficacement pour frapper (fléchir, orienter ses appuis, se mettre à distance).","En attaque : différencier son placement en coup droit et en revers (rotation de la ligne d’épaules en coup droit).","En attaque : identifier les espaces libres et produire une attaque ciblée.","En attaque : accélérer une balle favorable (smasher).","En défense : adopter une posture dynamique et mobile, permettant un déplacement équilibré."],"r":["Assurer le bon déroulement d’un match (mise en œuvre du règlement : décompte des points, annonce des « fautes », du score, …).","Prélever des indices simples pour identifier une situation favorable de marque (déséquilibre ou retard importants de l’adversaire au moment de sa frappe).","Apprécier globalement les raisons de son échec ou de sa réussite.","Assumer le rôle de partenaire d’entraînement."]},"Course en durée":{"cp":5,"a":"","p":["Éprouver le travail relatif à plusieurs mobiles.","Réaliser le test initial de VMA avec engagement.","Construire à 2 ou 3 élèves une partie de son entraînement : définir une charge de travail (durée, intensité des efforts, nature et durée de récupération).","Conduire sa séance en la régulant grâce aux paramètres connus","S’échauffer en intégrant prioritairement la mobilisation des articulations concernées.","Réaliser la séance complète en y intégrant systématiquement les éléments de récupération (hydratation, étirements, …).","Adopter une motricité spécifique.","Différencier globalement les allures en fonction du pourcentage de VMA","Adopter une technique de course/marche (placement, relâchement, amplitude/fréquence, action des bras, …) en lien avec l’objectif poursuivi.","Adapter sa respiration au type de travail. : intégrer une respiration en relation avec le rythme des appuis.","Prendre des repères et réguler son allure en étant guidé par un signal extérieur.","Exprimer son ressenti (mettre des mots sur des sensations)."],"r":["Autour de la coopération","Échanger avec autrui pour progresser.","Concevoir à plusieurs une échelle de ressenti général et respiratoire.","Observer la pratique d’autrui pour l’aider à partir d’indicateurs identifiés (état de fatigue, dégradation de l’attitude de course, …).","Organiser à plusieurs l’espace pour mettre en place le dispositif de course choisi (aller-retour, parcours en boucle…).","Autour du progrès personnel","Tenir un carnet d’entraînement","Utiliser des outils objectivant la zone d’effort (prise de pouls, cardiofréquencemètre) en correspondance avec les zones d’effort.","Retranscrire les écarts entre le « prévu » et le « réalisé ».","Réaliser un bilan global de sa séance."]},"Natation en durée":{"cp":5,"a":"","p":["Éprouver le travail relatif à plusieurs mobiles.","Intégrer progressivement plusieurs allures en fonction de l’intensité d’effort visé.","Pouvoir répéter une même allure dans une fourchette d’intensité donnée.","Conduire sa séance en la régulant grâce aux paramètres connus (nombre de répétitions, intensité, récupération.) : produire un échauffement spécifique au mobile poursuivi.","Conduire sa séance en la régulant grâce aux paramètres connus (nombre de répétitions, intensité, récupération.) : réaliser une séance complète.","Adopter une motricité spécifique : construire une technique de virage efficace.","Adopter une motricité spécifique : utiliser des techniques de nage ou d’actions motrices en rapport avec son projet d’entraînement.","Adapter sa respiration au type de travail. : expérimenter plusieurs rythmes respiratoires en fonction du choix de nage, de l’exercice et de l’allure.","Prendre des repères : chronométriques et de fréquence cardiaque pour organiser son travail.","Prendre des repères : visuels et proprioceptifs pour améliorer sa technique de nage.","Exprimer son ressenti (mettre des mots sur des sensations).","Appliquer les consignes de sécurité et d’hygiène."],"r":["Autour de la coopération : échanger avec autrui pour progresser.","Autour de la coopération : concevoir à plusieurs une échelle de ressenti (état général, aisance respiratoire, …).","Autour de la coopération : observer la pratique d’autrui pour l’aider.","Autour de la coopération : identifier des indicateurs permettant de situer un pratiquant dans sa zone d’effort (aisance respiratoire, tonicité/relâchement, dégradation progressive du geste).","Autour du progrès personnel : tenir un carnet d’entraînement","Autour du progrès personnel : utiliser des indicateurs objectivant la zone d’effort (Fréquence cardiaque, rythme respiratoire,.).","Autour du progrès personnel : retranscrire les écarts entre le « prévu » et le « réalisé ».","Autour du progrès personnel : réaliser un bilan global de sa séance"]},"Musculation":{"cp":5,"a":"","p":["Éprouver le travail relatif à plusieurs mobiles : tester des séances-types données par l’enseignant en fonction d’un mobile poursuivi.","Conduire sa séance en la régulant grâce aux paramètres connus.","Se remémorer les effets ressentis dans les jours qui suivent.","Expérimenter différents moyens pour s’échauffer (cordes à sauter, élastibandes, barre à vide, poids du corps…).","Adapter et personnaliser les charges en relation avec la charge maximale théorique.","Adopter une motricité spécifique.","Mobiliser ses segments avec des postures, des trajets qui préservent l’intégrité physique.","Préserver la qualité du placement jusqu’à la fin de la série.","Mettre en application les savoirs spécifiques sécuritaires (placement symétrique des mains, points d’appui, manipulation, réglage du matériel).","Contrôler la vitesse d’exécution, l’amplitude et le trajet moteur pendant toute la durée des séries.","Placer et rythmer une respiration en fonction du régime de contraction, du type d’exercice et du matériel utilisé (élastiques, charges additionnelles, poids du corps).","Prendre des repères sur soi et percevoir en fin de séance si les zones musculaires fatiguées correspondent aux groupes musculaires visés.","Exprimer son ressenti (mettre des mots sur des sensations)."],"r":["Autour de la coopération","Échanger avec autrui pour progresser.","Rendre compte des observations à son partenaire à l’issue du travail réalisé.","Concevoir en groupe une échelle de ressenti","Observer la pratique d’autrui pour l’aider, repérer : une dégradation du mouvement lors de la mobilisation d’une charge trop élevée,","Observer la pratique d’autrui pour l’aider, repérer : une posture dangereuse.","Autour du progrès personnel","Tenir un carnet d’entraînement.","Réaliser un bilan global de sa séance.","Retranscrire les écarts entre le « prévu » et le « réalisé »."]},"Step":{"cp":5,"a":"","p":["Éprouver le travail relatif à plusieurs mobiles : pour se développer, se dépasser, se confronter à ses limites.","Éprouver le travail relatif à plusieurs mobiles : pour s’entretenir, se remettre en forme, persévérer dans l’effort.","Éprouver le travail relatif à plusieurs mobiles : pour développer, synchroniser, complexifier sa motricité.","Conduire sa séance en la régulant grâce aux paramètres connus","A partir de l’objectif choisi, utiliser les paramètres adaptés permettant de respecter le registre d’effort en respectant la qualité de la réalisation, continue, dynamique et fluide.","Adopter une motricité spécifique : réaliser une séquence à partir d’un enchaînement « de base »; transposer à droite et à gauche les blocs imposés.","Adopter une motricité spécifique : respecter le rythme des BPM. Repérer le découpage d’une mesure.","Adopter une motricité spécifique : exécuter (concevoir les blocs), répéter (pour mémoriser et automatiser), s’engager (pour atteindre la zone d’effort ciblée).","Adopter une motricité spécifique : mobiliser ses segments avec des postures préservant l’intégrité physique.","Adapter sa respiration au type de travail (rythmer sa respiration en fonction de la gestuelle).","Prendre des repères (sur soi, sur l’extérieur) : utiliser un cardio- fréquence mètre pour situer sa zone d’effort ou à défaut, prendre son pouls entre chaque série.","Exprimer son ressenti (mettre des mots sur des sensations)."],"r":["Autour de la coopération","Échanger avec autrui pour progresser.","S’appuyer sur un élève « repère » pour aider le groupe à fonctionner.","Observer la pratique d’autrui pour l’aider.","Concevoir en groupe une échelle de ressenti (gradation des sensations).","Autour du progrès personnel","Tenir un carnet d’entraînement","Utiliser des outils objectivant la zone d’effort (prise de pouls, cardiofréquencemètre).","Retranscrire les écarts entre le « prévu » et le « réalisé ».","Réaliser un bilan de sa séance."]}},"N4":{"Demi-fond":{"cp":1,"a":"","p":["Assumer son projet et réaliser la meilleure performance sur une série de courses.","Maîtriser des allures de courses proches de la VMA sur des durées ou distances de plus en plus importantes.","Concevoir et réaliser un entrainement adapté aux effets recherchés.","S’entrainer en exploitant les différents modes de travail : capacité, puissance.","Récupérer de manière efficace et adaptée à l’effort réalisé.","Intégrer de plus en plus de repères sur soi (se libérer des repères externes).","Construire une attitude de course économique (efficiente)."],"r":["Concevoir un projet d’entrainement en précisant un volume de travail : nombre de répétitions, intensité de course, temps de récupération…","Recueillir sur soi, sur autrui des observations et en rendre compte.","Expliquer à son partenaire les conseils donnés.","Mettre en relation ces informations avec la course réalisée pour identifier les procédures mises en œuvre et comprendre le résultat.","Réguler son projet en fonction d’indicateurs recueillis et analysés.","Gérer en autonomie des prises de performances."]},"Course de haies":{"cp":1,"a":"","p":["Maintenir une vitesse élevée sur l’ensemble du parcours pour réaliser la meilleure performance.","Optimiser le franchissement en s’appuyant sur le contrôle de l’approche (prise d’informations, anticipation de l’appel).","Maîtriser sa vitesse d’approche.","Régulariser le nombre de foulée.","Ajuster sa distance d’impulsion.","Perfectionner le franchissement (impulsion vers l’avant, engagement du haut du corps, équilibre avec les segments libres, reprise active de la jambe d’attaque et retour rapide de la jambe de poussée (esquive.)","Rechercher : une attitude haute à l’approche de l’obstacle, une reprise d’appui dynamique et solide derrière la haie.","Organiser le nombre de foulées du départ au 1er obstacle en fonction de la jambe d’attaque.","Régulariser les choix de pied de départ, de jambe d’impulsion.de nombre de foulées…","Rester dynamique jusqu’à la ligne d’arrivée."],"r":["Automatiser la prise de repères sur l’ensemble de la course (franchissement et entre les obstacles, jusqu’à la ligne d’arrivée).","Observer pour soi et chez autrui les différents facteurs de continuité/discontinuité des actions, leur coordination, les stratégies possibles pour gérer la course (choix jambe d’attaque, lieu d’impulsion.) et en rendre compte.","Expliquer à son partenaire les conseils donnés.","Mettre en relation ses sensations avec le geste réalisé pour identifier les procédures et comprendre le résultat des actions,","Réguler ses actions en fonction d’indicateurs proprioceptifs (respiration, contraction / relâchement, équilibre / déséquilibre, accélération / décélération…).","Gérer un concours en autonomie."]},"Relais-vitesse":{"cp":1,"a":"","p":["Transporter le témoin le plus rapidement possible en optimisant les vitesses et leur coordination.","Fixer la position des relayeurs dans la course en fonction des ressources de chacun.","Utiliser avec pertinence la zone d’élan : dans sa totalité, ou partiellement en fonction des vitesses.","Le relayé : maîtriser des appuis dynamiques, son équilibre et sa trajectoire sur toute la distance à parcourir.","Le relayé : maintenir le témoin au milieu du couloir.","Le relayé : préciser le lieu de la transmission à l’intérieur de la zone.","Le relayé : préciser le moment du « hop » pour déclencher le placement de la main du partenaire.","Le relayé : conserver sa vitesse de course jusqu’à la sortie de la zone de transmission.","Le relayeur : partir très vite à la marque et maintenir cette allure de sprinter.","Le relayeur : au signal du partenaire, en pleine vitesse, tendre efficacement le bras sans perturber l’attitude de course, ni le rythme de celle-ci et placer la main pour recevoir le témoin.","Le relayeur : conserver l’oscillation des bras avec le témoin tant que la main du prochain relayeur n’est pas fixée pour recevoir le témoin."],"r":["Automatiser la prise de repères sur l’ensemble de la course.","Observer pour soi et chez autrui les différents facteurs de continuité/discontinuité des actions, leur coordination, les stratégies possibles pour gérer la course et en rendre compte","Expliquer à son partenaire les conseils donnés.","Mettre en relation ses sensations avec le geste réalisé pour identifier les procédures et comprendre le résultat des actions.","Réguler ses actions en fonction d’indicateurs proprioceptifs (contraction / relâchement, équilibre / déséquilibre, accélération / décélération…)."]},"Lancer de disque":{"cp":1,"a":"","p":["Lancer le plus loin possible en recherchant l’amplitude maximale de l’élan et la plus grande vitesse d’envol du disque.","Construire le relâchement du bras lanceur.","Allonger le chemin d’accélération du disque par une prise d’avance efficace des appuis pour une torsion optimale du corps.","Rechercher la continuité des actions propulsives de bas en haut, d’arrière en avant (jambes, tronc, bras) à partir d’appuis solides.","Savoir choisir sa stratégie de concours pour réaliser la meilleure performance en 6 tentatives."],"r":["Identifier dès le lâcher le bon placement du disque et la bonne trajectoire.","Automatiser la prise de repères pendant le lancer pour optimiser sa gestuelle (placer le regard, placer le bras libre…).","Observer sur soi et chez autrui les différents facteurs de continuité/discontinuité des actions bras/jambes et en rendre compte.","Expliquer à son partenaire les conseils donnés","Mettre en relation ses sensations avec le geste réalisé pour identifier les procédures et comprendre le résultat de ses actions.","Réguler ses actions en fonction d’indicateurs proprioceptifs (contraction / relâchement, équilibre / déséquilibre, accélération / décélération).","Gérer en autonomie un concours."]},"Lancer de javelot":{"cp":1,"a":"","p":["Lancer le plus loin possible en recherchant l’amplitude maximale de l’élan et la plus grande vitesse d’envol du javelot.","Construire le relâchement du bras lanceur (à partir du placement du bras libre,….)","Enchaîner efficacement « pas croisé » et double appui, tout en gardant le bras lanceur relâché en arrière,","Au niveau de la phase de double appui, renforcer la dissociation des appuis, orienter la coordination de leurs actions de l’arrière vers l’avant.","Rechercher la continuité des actions propulsives de bas en haut (jambes, tronc, bras) à partir d’appuis solides.","Prolonger l’alignement de l’axe gauche « appui-hanche-épaule »,","Intensifier le rythme de sa course d’élan à partir de prise de marques de plus en plus précise.","Savoir choisir sa stratégie de concours pour réaliser la meilleure performance en 6 tentatives."],"r":["Automatiser la prise de repères pendant le lancer pour optimiser sa gestuelle (direction du regard, placement du bras libre…).","Observer sur soi et chez autrui les différents facteurs de continuité/discontinuité des actions bras/jambes (rythme, déplacement dans l’axe,…) et en rendre compte.","Expliquer à son partenaire les conseils donnés.","Mettre en relation ses sensations avec le geste réalisé pour identifier les procédures et comprendre le résultat de ses actions.","Réguler ses actions en fonction d’indicateurs proprioceptifs (contraction / relâchement, équilibre / déséquilibre, accélération / décélération).","Gérer en autonomie un concours."]},"Saut en hauteur":{"cp":1,"a":"","p":["Sauter le plus haut possible en optimisant la continuité des actions et la production d’une impulsion maximale.","Contrôler l’élan (vitesse sous-maximale) pour accélérer les derniers appuis.","Réaliser une prise d’avance d’appuis (mettre en tension les loges musculaires de la jambe d’appel) et favoriser un appel vers le haut.","Utiliser les segments libres (jambe libre, bras) pour engager puis fixer le haut du corps.","Assurer efficacement la transmission des forces propulsives.","Choisir sa stratégie de concours pour réaliser la meilleure performance à partir d’un nombre limité (ou non) de sauts."],"r":["Automatiser la prise de repères pendant le saut (élan, impulsion, franchissement, réception…) pour optimiser sa technique.","Observer pour soi et chez autrui les différents facteurs de continuité/discontinuité des actions propulsives, leur coordination et en rendre compte.","Expliquer à son partenaire les conseils donnés.","Mettre en relation ses sensations avec le geste réalisé pour identifier les procédures et comprendre le résultat des actions,.","Réguler ses actions en fonction d’indicateurs proprioceptifs (contraction / relâchement, équilibre / déséquilibre, accélération / décélération).","Gérer en autonomie un concours."]},"Pentabond":{"cp":1,"a":"","p":["Sauter le plus loin possible en optimisant la continuité des actions et la qualité des actions propulsives.","Rechercher l’équilibre des bonds et la coordination des actions propulsives.","Utiliser un élan contrôlé et optimal (vitesse sous-maximale et marque intermédiaire) pour conserver la vitesse dans les derniers appuis et enchaîner l’appel.","Être gainé au moment de l’impulsion pour réaliser un étirement-renvoi efficace à chaque impulsion.","Perfectionner la dernière foulée pour coordonner l’appel et le cloche pied.","Conduire les bonds par une action de la jambe libre vers le haut et l’avant (genou fixé) pour les foulées bondissantes.","Utiliser les segments libres (bras) pour s’équilibrer pendant les phases aériennes du saut.","Assurer la transmission des forces propulsives par une fixation du bassin et du haut du corps.","Savoir réguler sa course d’élan (ajustement des marques d’appel) pour réaliser une performance maximale en un nombre limité de tentatives."],"r":["Automatiser la prise de repères pendant les différentes phases du pentabond pour optimiser sa technique","Observer pour soi et chez autrui les différents facteurs de continuité/discontinuité des actions propulsives, leur coordination et en rendre compte.","Expliquer à son partenaire les conseils donnés.","Mettre en relation ses sensations avec le geste réalisé pour identifier les procédures et comprendre le résultat des actions,","Réguler ses actions en fonction d’indicateurs proprioceptifs (contraction / relâchement, équilibre / déséquilibre, accélération / décélération…)","Gérer en autonomie un concours."]},"Natation de vitesse":{"cp":1,"a":"","p":["Nager vite en recherchant la continuité des actions propulsives.","Réaliser des trajets propulsifs offrant de plus larges appuis, perpendiculaires à l’axe de déplacement en accélération.","Gérer l’intensité de l’effort en fonction de la distance à parcourir.","Organiser avec pertinence la succession des nages.","Adopter un retour de bras vers l’avant, axé et ne perturbant pas l’équilibre, relâché (dans les nages alternées).","Adopter des coordinations bras-jambes efficaces, en optimisant les phases de glisse (dans les modes simultanés).","Utiliser et automatiser une expiration aquatique explosive, en fin de poussée des bras, quel que soit le mode nage.","Adopter des postures profilées, favorables à la glisse, au cours de la nage comme lors des virages (coulées).","Utiliser des techniques de virages permettant de gagner du temps lors des parties non-nagées.","Identifier le mode de nage adapté à une récupération efficace."],"r":["S’échauffer spécifiquement.","Comparer, en les éprouvant, différentes stratégies adaptées à ses propres ressources.","Confronter le ressenti (glisse, respiration….) avec des observations techniques pour réguler son projet de nage"]},"Natation de distance":{"cp":1,"a":"","p":["Équilibrer la vitesse de ses parcours pour pouvoir accélérer en fin de course.","Mobiliser davantage la hanche et accentuer le relâchement de la cheville afin d’accroître l’effet propulsif et équilibrateur du battement de jambes.","Réaliser des trajets propulsifs axés, orientés et accélérés.","Améliorer les techniques de virage et de coulée permettant un gain de distance et de temps.","Axer et allonger le retour des bras vers l’avant.","Adopter et automatiser une expiration aquatique complète, suivie d’une inspiration brève et réflexe, en fin de poussée des bras.","Élaborer un projet de nage personnalisé.","Adapter sa nage en fonction de son état de forme.","Adopter des postures profilées."],"r":["S’échauffer spécifiquement","Comparer, en les éprouvant, différentes stratégies adaptées à ses propres ressources","Mettre en relation les sensations de glisse et d’inconfort respiratoire ressenties avec les observations techniques réalisées par le professeur ou un camarade","Prédire son temps : projet."]},"Escalade":{"cp":2,"a":"","p":["En blocs, savoir mémoriser chaque mouvement et donner la pleine mesure de ses moyens.","Préparer le matériel nécessaire pour l’ascension (nombre de dégaines, longe, etc.).","Repérer les difficultés pour anticiper les choix de prises et les moments d’efforts soutenus.","Tenir et soutenir l’effort de façon optimale dans l’enchaînement de plusieurs voies.","S’adapter à l’espacement des prises et varier ses formes de mouvement (progresser en placement ou de façon dynamique).","Utiliser des positions de moindre effort et des attitudes de relâchement (« délayage ») pour s’économiser dans sa progression.","Aller vite dans les passages difficiles et évoluer avec fluidité et relâchement dans les passages plus faciles.","S’échauffer sans guidage de l’enseignant.","Diversifier les directions des forces (tracter, pousser, s’opposer, bloquer) amenant des positions de profil ou désaxées mais équilibrées (chandelle, drapeau, « lolotte »…).","Mettre de la pression sur les prises, progresser par la poussée des jambes dans des directions différentes.","Mousquetonner main droite ou main gauche dans des positions équilibrées, en respectant la hauteur de mousquetonnage (entre bassin et tête) et en utilisant plusieurs techniques possibles.","En situation de double assurage (moulinette et tête), assurer en moulinette avec une corde non tendue.","Assurer en étant mobile (avancer-mou, reculer-sec) et en se plaçant au mieux pour être au service du grimpeur."],"r":["Contrôler et corriger les erreurs possibles du grimpeur (vrille, corde sur la jambe).","Aider le grimpeur dans ses choix en cas de blocage.","Savoir assurer sans sécher son grimpeur au delà de la 3ème dégaine.","S’initier aux principes d’un assurage dynamique."]},"Course d’orientation":{"cp":2,"a":"","p":["Avant le déplacement : concevoir, prévoir, anticiper son itinéraire.","Optimiser le choix des postes en fonction de ses ressources (pour les formes de courses qui le permettent).","Concevoir rapidement son itinéraire à partir des éléments connus.","Construire son itinéraire en alternant des lignes de niveau 1 et 2 pour diminuer la distance de course (saut de lignes).","Se fixer des lignes d’arrêt simples.","Étalonner sa course.","Soutenir son effort pour mener à terme son projet d’itinéraire en un minimum de temps.","Utiliser la boussole pour définir un azimut, une visée.","Varier ses allures en fonction des prises de décision à effectuer au cours de l’itinéraire (course rapide sur chemin loin du poste, ralentie à l’approche de point de décision, lente à partir du point d’attaque).","Profiter des temps de récupération pour se repérer dans son projet de déplacement.","Adopter une attitude de course efficience.","Reconstruire son itinéraire en cas de perte momentanée ou de difficultés à découvrir le poste."],"r":["Argumenter ses choix d’itinéraires avec les autres.","Émettre différentes hypothèses relatives à l’échec ou à la réussite.","Optimiser le choix des postes en nombre et en qualité en fonction de ses ressources (et celles de ses partenaires).","Mémoriser une suite simple de points d’appui sur un parcours court."]},"Natation de sauvetage":{"cp":2,"a":"","p":["Pendant l’action : conduire, réguler, adapter son déplacement.","Réaliser un parcours avec obstacles verticaux et horizontaux impliquant des passages en immersion, sans s’arrêter en adaptant ses modes de déplacement. Sur une distance allant de 200 à 300 m par exemple.","Enchaîner des phases nagées, des phases d’apnée dynamique et des déplacements de remorquage.","Remorquer un mannequin enfant ou adulte sur une distance déterminée.","Affiner sa motricité spécifique.","Réaliser des plongeons canards en dosant l’angle d’immersion en fonction des caractéristiques de l’obstacle.","Coordonner des actions efficientes de jambes (ciseaux de jambes ou rétropédalage) et du bras libre (godille) pour faciliter le transport de l’objet ou du mannequin.","Choisir une prise de maintien du mannequin compatible avec sa vitesse de déplacement et la distance à parcourir.","Incliner le mannequin (parallèle à la surface de l’eau) afin de faciliter le remorquage."],"r":["Mettre en relation les sensations perçues lors du parcours avec les observations techniques réalisées par le professeur ou un camarade.","Analyser son parcours : comparer en les éprouvant, différentes stratégies adaptées à ses propres ressources (changer de nage en fin de parcours pour s’économiser avant la séquence de remorquage..)."]},"Acrosport":{"cp":3,"a":"","p":["Réalisation : maîtriser l’équilibre dans des postures variées et dynamiques : consolider les bases de la verticale renversée (blocage ceinture scapulaire, bassin au-dessus des épaules…), augmenter le volume et la hauteur de la figure (monter à la verticale des appuis du porteur…), réduire le nombre et la surface d’appui (CG au-dessus de la base de sustentation…).","Réalisation : assurer la continuité de l’enchaînement de figures, liaisons et déplacements plus complexes.","Réalisation : synchroniser les actions porteur/voltigeur : accompagnement actif, contact assuré jusqu’à la réception…","Réalisation : soutenir l’effort en maintenant la qualité d’attention et de précision lors des répétitions de l’enchaînement.","Composition : utiliser les variables de temps, d’espace et de formation pour varier les propositions et être original (synchronisé/décalé) ; (directions, étages, symétrie/dissymétrie), (ligne, séparé, groupe).","Composition : identifier le tempo du support sonore pour adapter la vitesse de réalisation et d’enchaînement des figures.","Appréciation-jugement : identifier les fautes techniques et d’exécution dans la fluidité de la réalisation.","Appréciation-jugement : juger de la pertinence de la composition choisie (espace orientation et occupation)."],"r":["Réalisation : s’échauffer de façon générale et spécifique en autonomie.","Réalisation : anticiper et adapter l’aide ou la parade (dosage selon le niveau du partenaire et placement pour ne pas gêner la présentation).","Réalisation : analyser sa prestation et mémoriser son rôle dans l’enchaînement des figures et dans le groupe.","Composition : exploiter le code de difficulté pour créer des figures plus virtuoses et plus esthétiques.","Composition : choisir les éléments en fonction des ressources du groupe.","Appréciation-jugement : repérer dans sa prestation et celle des autres, les fautes liées aux critères de réussite et de réalisation pour effectuer des corrections."]},"Aérobic":{"cp":3,"a":"","p":["Réalisation : coordonner et combiner une dizaine de pas à droite et à gauche complexifiés dans le temps (réalisés sur 8 ou 4 temps) ou dans la coordination (technique de pas plus complexe) et des difficultés de niveau A et B : Mémoriser (anticipation), Exécuter (postures, énergie, amplitude).","Réalisation : coordonner/dissocier les mouvements de bras et de jambes de manière simple (simultanés ou alternatifs, symétriques ou asymétriques).","Réalisation : repérer les temps forts (1er, 5ème) et compter les temps en suivant le tempo de la musique.","Réalisation : réaliser des formations et des changements avec des orientations différentes.","Réalisation : soutenir l’effort, en maintenant attention et précision, lors des répétitions de l’enchaînement.","Composition : varier l’espace corporel (Haut/debout, moyen, bas/au sol).","Composition : varier la dynamique de l’enchaînement en jouant sur les temps forts et faibles.","Appréciation-jugement : observer et apprécier la prestation d’un autre groupe à partir de critères variés.","Appréciation-jugement : repérer les points forts et les points faibles de la prestation d’un groupe."],"r":["Composition : présenter par écrit son enchaînement.","Composition : apprécier sa prestation régulièrement au regard des exigences de composition et remédier aux manques.","Appréciation-jugement : donner de nouvelles consignes pour enrichir la proposition."]},"Arts du cirque":{"cp":3,"a":"","p":["Le technicien : réaliser des figures ou routines complexes, approfondir et combiner des techniques, enchaîner, lier des éléments simples.","Le technicien : créer des figures inédites et singulières, prendre des risques en élevant, renversant, réduisant les surfaces d’appui, diversifiant les objets, les engins…","Le technicien : doser force et énergie pour intervenir, rectifier, modifier trajectoires ou équilibres.","Le technicien : choisir une ou deux techniques et y parfaire quelques figures originales.","Le technicien : proposer des figures inédites, périlleuses et singulières dans des conditions sécuritaires.","Le technicien : répéter, mémoriser des routines simples dans d’autres techniques afin de pouvoir s’inscrire dans des séquences collectives.","Le technicien : développer de nouvelles sensations kinesthésiques, proprioceptives pour contrôler son équilibre tout en décentrant son regard.","Le technicien : mémoriser le déroulement, la trame de la pièce sans s’appuyer sur un partenaire.","L'interprète : créer et jouer son personnage, pour dépasser le rôle du simple exécutant.","L'interprète : maintenir la qualité de l’interprétation lors des répétitions et de la présentation de la pièce.","Le metteur en scène : composer avec l'enseignant, en choisissant parmi plusieurs procédés, ceux qui servent le propos, l'intention: unisson, répétition..","Le metteur en scène : choisir, sélectionner les figures qui servent l’intention (le spectaculaire, l’émotion, le sens).","Le metteur en scène : situer chaque « moment » dans un espace pertinent non aléatoire.","Le metteur en scène : choisir les renforçateurs du propos: monde sonore, costumes, décors, maquillage, accessoires.","Le metteur en scène : diversifier les médias utilisés : instruments, voix, images vidéos, graphismes…","Le metteur en scène : le spectateur/lecteur","Le metteur en scène : garder en mémoire les tableaux principaux du spectacle (qui, où, quand) et émettre un avis sur la cohérence du canevas général du spectacle."],"r":["Le technicien : construire des signaux, regards pour communiquer, coopérer, sans chuter.","Le technicien : préparer son matériel et sa disposition avec minutie et anticipation.","Le technicien : le metteur en scène","Le technicien : structurer les différents modules en s’appuyant sur une trame identifiée et écrite : une fiche script du spectacle (ordre, trajets, rôles, matériel, accessoires) .","Le spectateur/ lecteur : lier l'observation de la qualité d'interprétation des circassiens (précision des figures, des déplacements, des regards, de l'engagement) aux émotions ressenties"]},"Danse":{"cp":3,"a":"","p":["Le danseur : créer une motricité de plus en plus complexe, diversifiée et originale au service du propos chorégraphique en jouant sur: L'exploration de différentes qualités d'appuis (nature, angle, durée, intensité, statiques ou dynamiques). La dissociation segmentaire et les coordinations de plusieurs parties du corps: droite/gauche, haut/bas, un segment du corps/ le reste du corps.. Le travail de l'équilibre/déséquilibre à partir de la conscience de l'axe. L'exploration de la notion de poids et de transfert.","Créer une motricité de plus en plus complexe, diversifiée et originale au service du propos chorégraphique en jouant sur: L'exploration de différentes qualités d'appuis (nature, angle, durée, intensité, statiques ou dynamiques). La dissociation segmentaire et les coordinations de plusieurs parties du corps: utiliser les paramètres du mouvement : l'espace, le temps, l'énergie, de façon variée, combinée et inventive pour nourrir le propos expressif.","Créer une motricité de plus en plus complexe, diversifiée et originale au service du propos chorégraphique en jouant sur: L'exploration de différentes qualités d'appuis (nature, angle, durée, intensité, statiques ou dynamiques). La dissociation segmentaire et les coordinations de plusieurs parties du corps: développer la notion de contact, l'accepter, l'explorer, donner son poids, recevoir celui de l'autre, varier les contacts et les relations avec les autres: pousser/tirer/transporter/maintenir, se servir de l'autre ou de son élan pour prolonger le mouvement.","Développer la notion de contact, l'accepter, l'explorer, donner son poids, recevoir celui de l'autre, varier les contacts et les relations avec les autres: savoir travailler à l'écoute des autres.","L'interprète : s'engager émotionnellement pour jouer son rôle : être disponible, vivant dans le regard, et oser être en scène.","L'interprète : maintenir la qualité de l’interprétation lors des répétitions et de la présentation de la chorégraphie.","Le chorégraphe : explorer, choisir et maîtriser différents procédés de composition avec l'enseignant qui permettront la construction du discours: l'aléatoire, la répétition, l'accumulation, la transposition..","Le chorégraphe : explorer différentes organisations de l'espace scénique et faire des choix qui soutiennent le propos chorégraphique.","Le spectateur/lecteur : analyser les procédés de composition et les relations entre les danseurs au regard du propos.","Le spectateur/lecteur : défendre son point de vue au cours d’un débat."],"r":["Le danseur/le chorégraphe : se répartir les rôles dans le groupe et se référer régulièrement à un regard extérieur, enseignant ou autre groupe d’élèves pour faire évoluer et enrichir sa chorégraphie.","Le spectateur : distinguer, dans son analyse, les critères objectifs de lecture (« ce que j’ai vu » comme procédés, mise en espace…) avec ceux plus subjectifs (« ce que j’ai ressenti, compris dans le propos… »)."]},"Gymnastique":{"cp":3,"a":"","p":["Réalisation : réaliser/ maîtriser les éléments gymniques et acrobatiques de niveau plus complexe pour les enchaîner sans rupture. (6 éléments au moins choisis dans 4 familles gymniques distinctes spécifiques à l'agrès).","Réalisation : réaliser les actions gymniques en situation plus complexe (combinaison, enchaînement d’actions).","Réalisation : réinvestir les acquis moteurs pour réaliser des éléments plus difficiles ou plus complexes.","Réalisation : maintenir un effort répété et optimal lors de la réalisation de l’enchaînement.","Composition : choisir l'ordre des éléments pour optimiser la réalisation de l’enchaînement (moments de respiration, gestion de l’effort, prise en compte de ses ressources).","Composition : organiser l'espace de l’enchaînement pour valoriser des moments particuliers de sa prestation.","Composition : appréciation","Composition : jugement","Composition : identifier le niveau de difficulté des éléments gymniques présentés.","Composition : apprécier les fautes d’exécution des éléments gymniques présentés."],"r":["Réalisation : s’échauffer de façon générale et spécifique en autonomie.","Réalisation : régler les agrès à sa morphologie et/ou à son niveau de pratique.","Réalisation : organiser l’espace du praticable ou l’aire d’évolution.","Réalisation : se placer pour parer de manière efficace, lors de la réalisation des éléments comme de l’enchaînement.","Appréciation – jugement : reconnaître la conformité des éléments choisis ainsi que celle de l'enchaînement, à partir de l’annonce de la séquence faite par l’élève gymnaste avant son passage (orale ou écrite).","Appréciation – jugement : repérer dans sa prestation et celle des autres, les fautes liées aux critères de réussite et de réalisation pour effectuer des corrections."]},"Gymnastique rythmique":{"cp":3,"a":"","p":["Réalisation : enrichir les manipulations d’engin par l’utilisation de paramètres différents (espaces, vitesses, éléments corporels plus complexes ou combinaison de deux des trois éléments).","Réalisation : enrichir les formations en jouant sur l'espace (agrandir, réduire les intervalles, jeu de niveaux), sur les éléments corps/engin (type et difficulté).","Réalisation : soutenir l’effort en maintenant la qualité de la réalisation et de l’interprétation au cours des répétitions de l’enchaînement.","Composition : utiliser des relations variées : (avec ou sans transmission, avec ou sans difficultés corporelles, nombre de partenaires, distance entre partenaires, éléments corps/engin diversifiés etc..) pour créer des effets sur le public.","Composition : développer la notion d’originalité lors des relations simples et intégrer la notion de « prise de risque maîtrisée ».","Composition : associer les exigences de réalisation motrice et l’intention dans le mouvement ; souci d’interpeller le public- élèves","Appréciation-jugement : identifier des fautes d’exécution constatées dans la réalisation.","Appréciation-jugement : repérer dans la prestation observée le niveau de difficulté de certains éléments la constituant.","Appréciation-jugement : repérer les choix opérés dans l’écriture chorégraphique."],"r":["Réalisation : s’échauffer pour une réalisation individuelle (maîtrise des éléments) et avec ses partenaires pour une réalisation collective en autonomie.","Composition : choisir les éléments corps/engin de façon pertinente en fonction des potentialités de chacun.","Composition : utiliser les moments de l’enchaînement facilitant la prise d’information pour agir ensemble dans des séquences à faible temps d’installation.","Composition : utiliser les éléments musicaux pour organiser les effets chorégraphiques : unisson, cascade, canon.","Appréciation-jugement : intégrer des critères de réalisation pour émettre un jugement.","Appréciation-jugement : repérer dans les productions le respect des règles comportementales pour effectuer des corrections."]},"Basket-ball":{"cp":4,"a":"","p":["Planifier et réaliser une préparation à l'effort individuelle et collective.","Au plan collectif : maintenir une organisation équilibrée dans la largeur et la profondeur dans la phase de montée de balle et dans le jeu placé près du panier.","Au plan collectif : créer et exploiter des espaces libres et des décalages par des enchaînements de passes et des fixations en dribbles utilisant le couloir central et les couloirs latéraux.","Au plan collectif : utiliser le jeu direct et indirect, le jeu en soutien si nécessaire.","Au plan collectif : mettre en place une défense organisée (tout terrain ou demi terrain) et articulée (aide défensive) pour protéger sa cible et récupérer la balle .","Au plan individuel : tenir et soutenir un effort optimal sur une succession de périodes de jeu","Au plan individuel : porteur de balle : S’orienter face à la cible et conserver la maîtrise du ballon sous la pression adverse. Rechercher en priorité le jeu direct : passe à un partenaire qui \"coupe\" vers la cible ou pénétration/fixation Réaliser des choix de tirs adaptés (tir en course ou tir bord de raquette) pertinents au regard de la situation et de ses caractéristiques techniques. Enchaîner ses actions (réception-passe, dribble-passe, dribble-tir, rebond offensif- tir…)","Au plan individuel : aide au porteur de balle : Se démarquer en priorité vers la cible en exploitant le couloir de jeu direct (ballon - cible) puis le libérer pour permettre une alternative de jeu au porteur de balle (passe ou 1c1 ) Enchaîner ses actions, varier ses démarquages. Participer au rebond offensif ou au repli défensif","Au plan individuel : défenseur : Adopter une posture défensive : cadrer les appuis du porteur de balle et reculer nettement sur le premier pas défensif pour maintenir la distance P /D. Utiliser les bras pour gêner la passe ou le tir dès que le dribble est arrêté. Ajuster son placement (aide ou pression) selon la position du ballon (pression côté ballon, à l'opposé du ballon se décentrer de son joueur pour stopper le PB qui a gagné son duel)"],"r":["Se concerter pour choisir une organisation adaptée aux caractéristiques de son équipe et à celle de l’adversaire (ex défense demi terrain, tout terrain)","Observer une séquence de jeu à l’aide de critères objectifs liés à l’efficacité collective lors des phases de transition et d’attaque placée","Arbitrer une rencontre à plusieurs avec partage des règles : siffler, signaler à la table de marque, faire appliquer la réparation."]},"Football":{"cp":4,"a":"","p":["Planifier et réaliser une préparation à l'effort individuelle et collective.","Au plan collectif : maintenir une organisation équilibrée dans la largeur et la profondeur (écartement et étagement).","Au plan collectif : créer et exploiter des espaces libres et des décalages par des enchaînements de passes utilisant le couloir central et les couloirs latéraux.","Au plan collectif : varier les situations de tir au but en créant et exploitant des espaces libres (couloir central, couloirs latéraux).","Au plan collectif : utiliser opportunément jeu en appui et jeu en soutien.","Au plan collectif : mettre en place une défense organisée sur 2 lignes pour récupérer la balle et protéger sa cible.","Au plan collectif : organiser la compensation des rôles.","Au plan individuel : tenir et soutenir un effort optimal sur une succession de périodes de jeu.","Au plan individuel : porteur de balle : Conserver la maîtrise de la balle sous pression adverse. Enchaîner ses actions (contrôle orienté-passe, conduite-passe…). Augmenter la vitesse du jeu par des passes appuyées dans les pieds ou dans la course du partenaire. Transmettre rapidement après fixation ou provoquer le duel.","Au plan individuel : aide au porteur de balle : Se démarquer par des appels variés (en appui, en soutien, dans le dos de la défense, entre les lignes.) et par recherche des intervalles pour recevoir la balle ou étirer la défense. Varier le rythme dans les appels de balle.","Au plan individuel : défenseur : Adapter son comportement au regard de son placement et de la position de la balle : presser le PB s’il est dans sa zone, se replacer vers sa cible en fermant l’axe ballon-cible, intercepter, couper les lignes de passe… Dissuader la passe adverse en marquant son adversaire direct."],"r":["Se concerter pour choisir une organisation adaptée aux caractéristiques de son équipe et à celle de l’adversaire.","Arbitrer une rencontre à plusieurs avec partage des règles : repérer, sanctionner et expliquer les fautes.","Observer une séquence de jeu à l’aide de critères objectifs liés à l’efficacité collective lors des phases d’attaque placée."]},"Handball":{"cp":4,"a":"","p":["Planifier et réaliser une préparation à l'effort individuelle et collective.","Au plan collectif : maintenir une organisation équilibrée qui occupe la largeur du terrain dans l’objectif d’écarter la défense adverse.","Au plan collectif : créer et exploiter des espaces libres par une circulation de balle exploitant toute la largeur du terrain et en privilégiant le décalage.","Au plan collectif : passer par-dessus la défense si celle-ci est trop aplatie.","Au plan collectif : utiliser opportunément jeu en appui et jeu en soutien.","Au plan collectif : mettre en place une défense adaptée autour de la zone pour protéger sa cible et récupérer la balle.","Au plan individuel : tenir et soutenir un effort optimal sur une succession de périodes de jeu.","Au plan individuel : porteur de balle : Faire une passe courte au partenaire qui s'engage dans un intervalle. Enchaîner un engagement balle en main pour aller au tir et une réorganisation du train supérieur pour transmettre la balle à un autre partenaire qui s'engage à son tour dans un intervalle. Tirer avec l'intention de viser des espaces difficiles à couvrir pour le gardien (tir dans les angles, tir avec un rebond au sol,…).","Au plan individuel : aide au porteur de balle : S'engager sans la balle dans l'espace libre entre deux défenseurs. en dissociant mes bras, orientés vers le passeur et mes jambes, orientées vers la cible. Enchaîner la réception de la balle avec une accélération dans l'intervalle et un tir en suspension vers l'avant.","Au plan individuel : défenseur : Harceler le porteur de balle. Toucher et contrôler le bras lanceur de l'attaquant afin de stopper le développement de l'attaque placée. Se déplacer en pas chassés pour fermer les intervalles. Intercepter une passe hasardeuse d'un attaquant."],"r":["Se concerter pour choisir une organisation adaptée aux caractéristiques de son équipe et à celle de l’adversaire (défense plus ou moins étagée).","Observer une séquence de jeu à l’aide de critères objectifs liés à l’efficacité collective lors des phases d’attaque placée.","Arbitrer une rencontre à plusieurs avec partage des règles : repérer, sanctionner et expliquer les fautes."]},"Rugby":{"cp":4,"a":"","p":["Planifier et réaliser une préparation à l'effort individuelle et collective.","Au plan collectif : alterner les formes de jeu appropriées aux faiblesses de l’adversaire.","Au plan collectif : exploiter les espaces libres et les surnombres en fixant puis en transmettant.","Au plan collectif : glisser ensemble sur les côtés sans se laisser aspirer par le ballon, en faisant confiance à ses partenaires.","Au plan collectif : reformer une ligne défensive après plusieurs temps de jeu.","Au plan individuel : tenir et soutenir un effort optimal sur une succession de périodes de jeu","Au plan individuel : porteur de balle : Créer et exploiter un surnombre. Jouer en avançant : fixer, percuter, libérer… Passer à des joueurs en mouvement. Chercher à prendre un intervalle pour franchir ou progresser. Opérer les choix de relance appropriés au dispositif défensif.","Au plan individuel : aide au porteur de balle : Être efficace dans le soutien debout et au sol (en vue de faire des transformations rapides du jeu).","Au plan individuel : défenseur : Moduler la vitesse de montée en fonction des partenaires et du rapport de force. Enchaîner les tâches pour harceler, freiner, intercepter, bloquer, plaquer, arracher… Ralentir la sortie de balle et/ou la récupérer par la poussée. Se replacer sans être hors jeu malgré l’augmentation des temps de jeu."],"r":["Concevoir un projet collectif : se donner les moyens de le mettre en œuvre;","Repérer la pertinence (ou non) d’actions individuelles ou collectives.","Co-arbitrer avec des règles plus élaborées. Savoir se déplacer pour être plus efficace dans la lecture du jeu."]},"Volley-ball":{"cp":4,"a":"","p":["Planifier et réaliser une préparation à l'effort individuelle et collective.","Au plan collectif","S’organiser pour rompre l’échange de façon majoritairement décisive par une attaque placée ou accélérée.","S’organiser avec une défense haute sur balles accélérées et une défense basse sur les balles placées.","Au plan individuel : tenir et soutenir un effort optimal sur une succession de périodes de jeu.","Au plan individuel : porteur de balle : Prendre les informations le plus tôt possible sur les trajectoires afférentes et adapter sa posture en conséquence. En zone avant, choisir l'alternance continuité (relayeur) ou rupture (attaque du terrain adverse). Construire le temps d’engagement pour l’attaque (je démarre quand le ballon est au sommet de sa trajectoire). Produire des mises en jeu variées en direction et en force","Au plan individuel : aide au porteur de balle : Proposer un soutien actif au porteur par sa disponibilité (appuis dynamiques, orientation, communication).","Au plan individuel : défenseur : Produire des trajectoires régulièrement hautes et précises vers le relayeur (par des frappes maîtrisées en force et en direction). Différencier ses postures suivant le type d'attaque produite et son poste sur le terrain (jambes fléchies ou en suspension : contre). Compenser dans la zone laissée vacante par un partenaire."],"r":["Observer pour conseiller de façon constructive.","Recueillir des données objectives pour en faire part à mes partenaires lors des temps morts (espaces libres dans le jeu adverse, joueurs à éviter lors de la mise en jeu..) et collaborer au projet collectif."]},"Judo":{"cp":4,"a":"","p":["Planifier et réaliser une préparation à l’effort individuelle.","Combat debout : construire une stratégie d’attaque personnelle : saisie (kumi-kata) adaptée à mon projet et posée en 1er ; imprimer les déplacements, provoquer une réaction ou un déplacement prévisible…","Combat debout : se donner les conditions de réussite dans l’attaque : continuité d’actions amenant à un déséquilibre significatif, attaque dans le sens du déséquilibre provoqué…","Combat debout : s’adapter à la réaction adverse : redoubler l’attaque ou enchaîner sur un amené au sol suite au déséquilibre initial : liaison debout-sol.","Combat debout : élargir son panel de techniques debout, pratiquer les techniques à droite et à gauche.","Combat debout : adapter ses actions face à différents gabarits.","Combat debout : amorcer un enchaînement après esquive sur une attaque adverse inefficace.","Combat au sol : saisie (kumi-kata) adaptée à mon projet et posée en 1er ; imprimer les déplacements, provoquer une réaction ou un déplacement prévisible…","Combat au sol : élargir son panel de techniques au sol en variant les saisies et les formes de retournements.","Combat au sol : préparer un retournement préférentiel par une saisie appropriée et en faisant réagir son adversaire afin de profiter de sa force.","Combat au sol : enrichir les solutions de sorties d’immobilisation (sortir de la surface de combat).","Combat au sol : savoir exploiter les opportunités offertes par l’attaquant (bras ou jambe engagé) pour renverser le rapport de force et changer de statut dominant/dominé.","Tenir et soutenir un effort sur une succession de combats.","Gérer l’investissement énergétique pour accélérer au moment voulu."],"r":["Assurer le rôle de partenaire d’entraînement et réguler son action afin d’optimiser l’apprentissage du partenaire.","Assurer le rôle d’observateur et de conseiller.","Analyser ses réussites et ses échecs pour en retirer les leçons.","Varier les formes d’affrontement et changer d’adversaires afin d’enrichir l’expérience du combattant.","Respecter un niveau d’adversité défini dans un combat à thème (accepter la chute ou de ne pas contre-attaquer) pour des besoins d’apprentissage.","Assurer le rôle d’arbitre et se positionner efficacement.","Gérer un tournoi en tant que juge."]},"Boxe française":{"cp":4,"a":"","p":["Planifier et réaliser une préparation à l’effort individuelle.","Préparer l’attaque pour toucher précisément : ajuster sa distance de touche à l’adversaire (déplacement et placement), le perturber, feinter…","Développer l’attaque en restant équilibré et protégé (enchaîner armer-toucher-réarmer- pas de retrait en fin d’attaque).","Neutraliser l’attaque adverse par des parades appropriées.","Exploiter la neutralisation en contre-attaquant.","Tenir et soutenir un effort sur une succession d’assaut."],"r":["Assurer le rôle de partenaire d’entraînement et réguler son action afin d’optimiser l’apprentissage du partenaire.","Effectuer des enchaînements d’actions variés, en attaque et en défense, dans des contextes variés.","Mettre en relation le résultat des actions avec le projet initialement formalisé.","Réguler les choix décisionnels et construire des « systèmes » d’attaque et de défense pertinents.","Faire varier la nature et la quantité d’incertitude.","Comme juge, identifier seulement les actions qui touchent précisément et réglementairement.","Assurer le rôle d’arbitre et se positionner efficacement.","Déterminer le gagnant de chaque reprise ou de l’assaut en comptabilisant la cotation de chaque touche.","Comparer son résultat de jugement avec les autres juges à l’issue de l’assaut.","Varier les formes d’affrontement, changer d’adversaires afin d’enrichir l’expérience du combattant."]},"Badminton":{"cp":4,"a":"","p":["Planifier et réaliser une préparation à l’effort général et spécifique.","Tenir et soutenir un effort sur la durée (succession de périodes de jeu).","Se renforcer spécifiquement.","En attaque : identifier sa situation dans le rapport de force et adapter sa réponse.","En attaque : systématiser une posture dynamique pré-active d’attaque ou de défense (tête de raquette haute, jambes fléchies, coude libre).","En attaque : produire des enchaînements de frappes variées pour : Créer / exploiter des espaces libres et mettre l’adversaire en crise spatio-temporelle. Créer / exploiter une situation favorable de marque (amener l’adversaire à remonter le volant en vue d’un smash ou d’un kill ou amener l’adversaire à jouer un revers de fond de court, …).","En attaque : neutraliser : trouver des solutions pour créer un changement de rapport de force (produire des frappes à plat sur des frappes descendantes, réduire les angles de retour, …).","En attaque : stabiliser et améliorer la qualité de ses frappes (précision, puissance, trajectoire)","En attaque : diversifier ses coups d’attaque en gardant une préparation identique (smash, amorti, dégagé offensif, croisé et décroisé).","En défense : effectuer un sursaut d’allègement juste avant la frappe de l’adversaire et retomber au moment de la frappe pour optimiser le déplacement","En défense : avoir des solutions de renvoi sur les coups préférentiels de l’adversaire."],"r":["Assumer le rôle de partenaire d’entraînement et réguler son action pour optimiser l’apprentissage de son partenaire.","Conseiller un joueur à partir de caractéristiques repérées sur lui et son adversaire.","Analyser ses choix tactiques au regard de ceux de l’adversaire.","Analyser et expliciter les raisons de l’échec ou de la réussite dans le match.","Être capable d’organiser un tournoi au sein de la classe."]},"Tennis de table":{"cp":4,"a":"","p":["Planifier et réaliser une préparation à l’effort général et spécifique.","Tenir et soutenir un effort sur la durée (succession de périodes de jeu.","Se renforcer spécifiquement.","En attaque : construire le point à partir du service et de la probabilité de retour (schémas tactiques simples).","En attaque : assurer des services différents pour créer de l’incertitude et éviter un retour décisif de l’adversaire.","En attaque : créer le déséquilibre adverse en variant rapidement l’enchaînement des frappes.","En attaque : varier la fréquence de l’échange (jouer la balle plus tôt après le rebond pour prendre l’adversaire de vitesse ou plus tard pour s’accorder plus de temps).","En attaque : produire des trajectoires rasantes pour accélérer le jeu.","En défense : perturber le renvoi par la production de rotations de balle, au service et dans l’échange.","En défense : produire des trajectoires rasantes pour limiter la prise d’initiative adverse.","En défense : effectuer des déplacements spécifiques équilibrés (fentes, pivot, pas chassés, pas glissés)","En défense : prendre des informations sur le coup adverse pour adapter sa réponse."],"r":["En tant qu’observateur, conseiller un joueur à partir de caractéristiques repérées sur lui et son adversaire.","Émettre différentes hypothèses relatives à l’échec ou à la réussite.","Utiliser les temps de pause pour analyser son jeu et élaborer un projet tactique.","Assumer le rôle de partenaire d’entraînement et réguler son action pour optimiser l’apprentissage de son partenaire."]},"Course en durée":{"cp":5,"a":"","p":["Poursuivre un unique mobile d’agir que l’on peut justifier.","Concevoir progressivement ses séances de façon autonome et personnalisée.","S’échauffer en se centrant sur les mobilisations articulaires qui nécessitent une attention particulière en fonction du vécu personnel (fragilités éventuelles) et selon un principe de progressivité.","Concevoir une séance réaliste (volume de travail réalisable pour soi dans le temps imparti) et recherchant des effets attendus (charge de travail suffisante et ciblée).","Agir sur les paramètres d’intensité d’effort pour concevoir son entraînement.","Réaliser des enchaînements de séquences de course/marche avec une récupération adaptée.","Affiner sa motricité spécifique en fonction des choix : adapter sa technique de course (placement, pose du pied, rythme des appuis, rythme respiratoire …) en fonction de l’allure.","Affiner sa motricité spécifique en fonction des choix : intégrer différentes allures de déplacement en fonction de l’intensité visée.","Prendre des repères progressivement intériorisés.","Utiliser sa Fréquence Cardiaque comme repère possible (notamment pour la récupération).","Passer de repères extéroceptifs (chronomètre, plots, signal sonore) à des repères intéroceptifs.","Éprouver des séquences parfois longues et /ou « coûteuses » pour en repérer les effets.","Exprimer son ressenti selon divers critères (respiratoires, cardiaques, musculaires, motivationnels)."],"r":["Autour de la coopération","Justifier son choix de mobile à partir de déterminants personnels et expliquer les contenus de la séance à partir des connaissances.","Échanger avec autrui sur les effets de son action.","Affiner et compléter son échelle de ressenti.","Autour du progrès personnel","Utiliser son carnet d’entraînement pour prévoir à plus long terme en tenant compte du ressenti.","Analyser les écarts entre le « prévu » et le « réalisé ».","Identifier et comparer son ressenti d’une série à l’autre.","Comparer les différentes séances d’entraînement pour un même objectif.","Prendre des repères extéroceptifs et les mettre en relation avec le ressenti proprioceptif.","Utiliser les TICE pour mémoriser et contrôler le travail réalisé."]},"Natation en durée":{"cp":5,"a":"","p":["Poursuivre un unique mobile d’agir que l’on peut justifier.","Concevoir progressivement ses séances de façon autonome et personnalisée.","Concevoir une séance réaliste (volume de travail réalisable pour soi dans le temps imparti) mais produisant des effets attendus (charge de travail suffisante et ciblée).","Agir sur les paramètres : séries, répétitions, intensité (% de VMA ou FC), récupération pour produire un effort cohérent avec le mobile poursuivi et avec les données théoriques.","Affiner sa motricité spécifique en fonction des choix.","Concevoir et réaliser un échauffement spécifique au mobile choisi et tenant compte du vécu personnel (fragilité ou ancienne blessure, état de forme).","Adapter sa technique de nage (fréquence des cycles bras/jambes, rythme respiratoire …) en fonction de l’allure.","Prendre des repères progressivement intériorisés pour réguler son allure en restant dans la zone d’effort visée.","Éprouver des séquences longues et /ou « coûteuses » pour en repérer les effets à court et moyen terme.","Exprimer son ressenti selon divers critères (respiratoires, musculaires, motivationnels)."],"r":["Autour de la coopération","Échanger avec autrui sur les effets de son action.","Affiner et compléter son échelle de ressenti.","Autour du progrès personnel","Utiliser son carnet d’entraînement pour prévoir à plus long terme.","Analyser les écarts entre le « prévu » et le « réalisé ».","Réaliser un bilan global de sa séance selon des critères prédéfinis (bilan respiratoire, musculaire, motivationnel technique, intensité perçue) afin de réguler la séance suivante.","Utiliser les TICE pour mémoriser et contrôler le travail réalisé."]},"Musculation":{"cp":5,"a":"","p":["Poursuivre un unique mobile d’agir que l’on peut justifier.","Concevoir progressivement ses séances de façon autonome et personnalisée.","Concevoir une séance réaliste (volume de travail réalisable pour soi dans le temps imparti) mais produisant des effets attendus (charge de travail suffisante et ciblée).","Agir sur les paramètres d’intensité d’effort pour réguler son entraînement à partir du bilan personnel de séance (séries, répétitions, charge, récupération) pour produire un effort optimal conforme au mobile poursuivi et aux données théoriques.","Affiner sa motricité spécifique.","Personnaliser l’échauffement en fonction du mobile et de son vécu personnel (fragilité ou blessures antérieures).","Différencier sa respiration en fonction du mouvement effectué (expiration en fin de poussée, inversion expiration/inspiration sur des mouvements d’ouverture).","S’étirer spécifiquement en fin de séance voire entre chaque série.","Exprimer son ressenti selon divers critères (respiratoires, musculaires, motivationnels)"],"r":["Autour de la coopération","Échanger avec autrui sur les effets de son action.","Élaborer une échelle de ressenti permettant de graduer ses sensations en lien avec le travail réalisé.","Autour du progrès personnel","Utiliser son carnet d’entraînement pour prévoir à plus long terme en tenant compte du ressenti.","Retranscrire le travail réalisé et analyser les écarts éventuels entre le « prévu » et le « réalisé ».","Mettre en lien les ressentis, les données scientifiques, le contenu retranscrit des séances précédentes pour réguler son action.","S’organiser à deux ou trois pour placer les charges, alterner les passages, gérer le temps de récupération…","Utiliser les TICE pour mémoriser et contrôler le travail réalisé"]},"Step":{"cp":5,"a":"","p":["Poursuivre un unique mobile d’agir que l’on peut justifier.","Concevoir progressivement ses séances de façon autonome et personnalisée.","Personnaliser l’échauffement en fonction du mobile et de son vécu personnel (fragilité ou blessures antérieures ).","Concevoir une séance réaliste (volume de travail réalisable pour soi dans le temps imparti) mais produisant des effets attendus (charge de travail suffisante et ciblée).","Agir sur les paramètres (séries, répétitions, durée, intensité récupération) pour produire un effort cohérent avec le mobile poursuivi et les données théoriques (augmentation de l’intensité pour le mobile 1, augmentation de la durée pour le mobile 2, augmentation de la complexité pour le mobile 3).","Affiner sa motricité spécifique en fonction des choix.","Utiliser certains paramètres pour réguler son action pendant la réalisation : amplitude du mouvement, impulsions, combinaison de pas, un pas sur deux,…","Prendre des repères progressivement intériorisés pour réguler l’intensité de son enchaînement.","Exprimer son ressenti selon divers critères (respiratoires, musculaires, engagement)."],"r":["Autour de la coopération","Échanger avec autrui sur les effets de son action.","Se coordonner avec les membres du groupe pour composer l’enchaînement collectif en conservant sa propre zone d’effort (fourchette de FC).","Conseiller un camarade pour l’aider à viser sa zone d’effort optimal.","Autour du progrès personnel","Utiliser son carnet d’entraînement pour prévoir à plus long terme en tenant compte du ressenti.","Analyser les écarts entre le « prévu» et le « réalisé » et affiner l’identification des difficultés rencontrées.","Utiliser les TICE pour mémoriser et contrôler le travail réalisé."]}}};
